function personagemAparencia() { return Object.assign({}, PERSONAGEM.aparencia, { nomeCamisa: PERSONAGEM.nomeCamisa }); }
const salvo = {
  ler(chave, padrao) { try { const v = localStorage.getItem(chave); return v ? JSON.parse(v) : padrao; } catch (e) { return padrao; } },
  gravar(chave, valor) { try { localStorage.setItem(chave, JSON.stringify(valor)); } catch (e) { /* sem espaço/privado */ } },
};

// Elenco do time (16 jogadores). Sorteado na primeira vez e salvo. Os nomes não se repetem entre times enquanto o banco
// tiver nomes livres.
// O elenco guarda só NOME + GÊNERO + SEMENTE: a aparência é montada a cada partida pelo MESMO banco do criador de
// personagem (gerarAparencia) — cortes, barbas, rostos, lábios, tons de pele, chuteiras... Assim, todo corte/rosto/chuteira
// novo que entrar no criador já aparece nos jogadores. Cada time tem um elenco masculino e um feminino (o misto junta 8 + 8).
// Os nomes masculinos são os mesmos de antes (elencos.v1), para o histórico (suspensões, lesões) continuar valendo.
function elencoDoTime(time, genero) {
  if (time.elenco) return time.elenco;               // time da história: elenco fixo, não sorteia nem salva
  const g = genero === 'F' || genero === 'X' ? genero : 'M';
  const todos2 = salvo.ler('futebolJs.elencos.v2', {});
  const E = todos2[time.id] = todos2[time.id] || {};
  const sortear = (sexo) => {
    if (E[sexo] && E[sexo].length >= 16) return;
    let nomes = null;
    if (sexo === 'M') { const v1 = salvo.ler('futebolJs.elencos.v1', {}); if (v1[time.id] && v1[time.id].length >= 16) nomes = v1[time.id].map((j) => j.nome); }
    if (!nomes) {
      const usados = new Set(Object.values(todos2).flatMap((x) => [...(x.M || []), ...(x.F || [])]).map((j) => j.nome));
      const banco = sexo === 'F' ? NOMES_F : NOMES, livres = banco.filter((n) => !usados.has(n)), fonte = livres.length >= 16 ? livres : banco.slice();
      nomes = []; for (let i = 0; i < 16; i++) nomes.push(fonte.splice(Math.floor(Math.random() * fonte.length), 1)[0]);
    }
    E[sexo] = nomes.map((nome) => ({ nome, genero: sexo, semente: (Math.random() * 4294967296) >>> 0 }));
    salvo.gravar('futebolJs.elencos.v2', todos2);
  };
  if (g !== 'F') sortear('M');
  if (g !== 'M') sortear('F');
  const lista = g === 'X' ? E.M.slice(0, 8).flatMap((j, i) => [j, E.F[i]]) : E[g];
  return lista.map((j) => Object.assign({}, j, gerarAparencia(j.semente, j.genero)));
}

// ---------------------------------------------------------------------
// GERADOR DE APARÊNCIA — usa as listas do criador de personagem (PELES_FITZ, CORES_CABELO, ESTILOS_CABELO,
// ESTILOS_BARBA, ROSTOS, LABIOS, CHUTEIRAS). Cada corte/rosto pode ter g: 'M' | 'F' | 'U' (unissex). Sem g, vale a lista
// abaixo; um corte NOVO sem classificação conta como unissex. Rostos com cílios/batom/delineado/blush... são só femininos.
// Barba só nos homens. A semente faz o mesmo jogador ficar sempre igual.
// ---------------------------------------------------------------------
const CABELO_GENERO = {
  M: [3, 4, 5, 6, 7, 9, 15, 17, 18, 19, 21, 25, 26],                        // careca, raspado, militar, degradê, topete, social, pompadour...
  F: [30, 31, 32, 33, 34, 35, 36, 37, 39, 40, 41, 42, 43, 44],             // chanel, franja reta, maria-chiquinha, tranças, coques, emo...
  // os outros (curto, volumoso, para trás, franja, black power, cacheados, longo liso, coque longo, bagunçado, tigela, rabo de cavalo,
  // dreads, mullet, repicado, pixie...) são UNISSEX
};
const CHANCE_CORTE_LOJA = 0.12;                                          // de cada 100 NPCs, uns 12 com um corte da loja
const generoDoCabelo = (i) => { const h = ESTILOS_CABELO[i]; if (h && h.g) return h.g; return CABELO_GENERO.M.includes(i) ? 'M' : CABELO_GENERO.F.includes(i) ? 'F' : 'U'; };
const generoDoRosto = (i) => { const r = ROSTOS[i]; if (!r) return 'U'; if (r.g) return r.g; return /cilios|batom|delineado|sombra|blush|pinta/.test(r.extra || '') ? 'F' : 'U'; };
function gerarAparencia(semente, genero) {
  const r = sorteador(semente || 1), pick = (lst) => lst[Math.floor(r() * lst.length)];
  const pesado = (pesos) => { let t = 0; for (const w of pesos) t += w; let x = r() * t; for (let i = 0; i < pesos.length; i++) { x -= pesos[i]; if (x <= 0) return i; } return pesos.length - 1; };
  const fem = genero === 'F';
  const iPele = pesado([1, 1.5, 2.5, 3, 3, 2.5]), pele = PELES_FITZ[Math.min(iPele, PELES_FITZ.length - 1)].cor;
  const iCor = pesado([30, 24, 18, 9, 7, 3, 2, 1].slice(0, CORES_CABELO.length)), cabelo = CORES_CABELO[iCor].cor;
  const cortes = [], loja = [], ok = fem ? 'F' : 'M';
  ESTILOS_CABELO.forEach((h, i) => { const g = generoDoCabelo(i); if (h.cosmetico) { if (g === ok || g === 'U') loja.push(i); return; } if (g === ok) cortes.push(i, i); else if (g === 'U') cortes.push(i); });   // do próprio gênero vale em dobro
  let estilo = pick(cortes);
  // os cortes da LOJA (cosmeticos.js, vendidos na barbearia) aparecem em alguns NPCs. Sorteio à parte, com a mesma semente:
  //   o resto da aparência de cada um continua igual, com ou sem o cosmeticos.js carregado.
  if (loja.length) { const r2 = sorteador(((semente || 1) * 7919 + 104729) | 0); if (r2() < CHANCE_CORTE_LOJA) estilo = loja[Math.floor(r2() * loja.length)]; }
  const rostosNeutros = [], rostosF = [];
  ROSTOS.forEach((x, i) => (generoDoRosto(i) === 'F' ? rostosF : rostosNeutros).push(i));
  const rosto = fem && rostosF.length && r() < 0.55 ? pick(rostosF) : (r() < 0.35 ? 0 : pick(rostosNeutros));
  const comBarba = ESTILOS_BARBA.map((b, i) => i).filter((i) => i > 0 && !ESTILOS_BARBA[i].cosmetico);           // (as da loja ficam de fora: sorteio à parte, abaixo)
  let barba = fem ? 0 : (r() < 0.5 ? 0 : comBarba[Math.floor(r() * comBarba.length)]);
  const lojaB = fem ? [] : ESTILOS_BARBA.map((b, i) => i).filter((i) => ESTILOS_BARBA[i].cosmetico);
  if (lojaB.length) { const r3 = sorteador(((semente || 1) * 6151 + 49157) | 0); if (r3() < CHANCE_CORTE_LOJA) barba = lojaB[Math.floor(r3() * lojaB.length)]; }
  const labio = clamp(Math.round(iPele * 1.3 + (r() * 2 - 1)), 0, LABIOS.length - 1);
  return { pele, cabelo, estilo, barba, rosto, labio: LABIOS[labio] ? labio : 3, corBarba: cabelo, chuteira: (() => { const L = chuteirasLivres(); return L[Math.floor(r() * L.length)]; })(),   /* (7.1.10) as premium da loja ficam de fora */ manga: r() < 0.15 ? 1 : 0, meiao: r() < 0.12 ? 2 : r() < 0.1 ? 0 : 1, genero: fem ? 'F' : 'M', enfeites: (() => { try { return enfeitesNPC(semente, fem); } catch (e) { return null; } })() };
}

// Seu técnico: nome e aparência sorteados na primeira vez e salvos ('futebolJs.tecnico.v1').
// Para mudar: FutebolJS.salvarTecnico({ nome, aparencia: { pele, cabelo, estilo, roupa } }).
function tecnicoDoUsuario() {
  let t = salvo.ler('futebolJs.tecnico.v1', null);
  if (!t) {
    t = { nome: NOMES_TECNICO[Math.floor(Math.random() * NOMES_TECNICO.length)],
      aparencia: { pele: PELES[Math.floor(Math.random() * PELES.length)], cabelo: CABELOS[Math.floor(Math.random() * CABELOS.length)], estilo: Math.floor(Math.random() * 3), roupa: '#1D2A44' } };
    salvo.gravar('futebolJs.tecnico.v1', t);
  }
  return t;
}

// ---- A partida padrão (a de teste da tela inicial). Tudo opcional em novaPartida().
const PARTIDA_PADRAO = {
  campo: 'estadio',                 // chave de CAMPOS ou um objeto de campo
  times: ['azulao', 'ataliba'],     // [o seu time, o adversário] (chaves de TIMES ou objetos)
  mandante: 0,                      // de quem é o estádio (pesa na torcida)
  competicao: { tipo: 'amistoso', nome: 'Amistoso', rodada: 0, fase: '', mataMata: false, jogo: 'unico', placarIda: null },
  dificuldade: 'normal',
  clima: 'seco',                    // 'seco' | 'chuva' | 'neve'
  gramado: 'baixo',                 // 'baixo' | 'alto'
  horario: 'noite',                 // 'dia' | 'tarde' | 'noite'
  duracao: 300,                     // segundos de relógio: DURACOES.padrao (5 min) ou DURACOES.rapida (3 min)
  usuario: { nome: 'Você', posicao: 'FWD' },   // posição do seu jogador: 'FWD' | 'MID' | 'DEF'
  taticas: [null, null],            // null = a preferida do time
  formacoes: [null, null],
  arbitro: null,                    // null = o juiz de sempre; ou os dados de um boneco (ver HIST.professor) para outro apitar
};
let PARTIDA = null;                // a partida em andamento (montada por montarPartida)
const DURACOES = { padrao: 300, rapida: 180 };   // partida normal (5 min) e partida rápida (3 min)

// ---------------------------------------------------------------------
// (7.4.6) CALENDÁRIO DA HISTÓRIA: o dia do save (dados.dia, que só cresce: 1, 2, 3...) vira DIA E MÊS. Todo mês tem 30 dias e o
//   ano tem 12 meses (360 dias). O dia da semana continua o de sempre (o dia 1 é uma segunda). Guardado no save da cidade:
//   calJan = o dia (do save) que é 1º de janeiro do ano calAno.
//   · Antes da peneira (o passado da história) o dia 1 é 1º de fevereiro de dois anos atrás.
//   · "Dois anos depois", na peneira, o calendário é acertado: a peneira é em 8 de janeiro do ano de hoje, a carta chega dias
//     depois e a temporada começa no fim de janeiro (como a Série A de 2026: de 28 de janeiro a 2 de dezembro).
//   · Saves de antes da 7.4.6 que já estão na carreira: o 1º jogo da temporada atual vira 28 de janeiro.
//   A TEMPORADA (serieb.js): janeiro a maio jogando, JUNHO livre (a janela de transferências do meio do ano), julho a novembro
//   jogando e DEZEMBRO de férias (a outra janela); em janeiro começa a próxima.
// ---------------------------------------------------------------------
const Calendario = (() => {
  const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
  const CURTOS = ['jan', 'fev', 'mar', 'abr', 'mai', 'jun', 'jul', 'ago', 'set', 'out', 'nov', 'dez'];
  const anoHoje = () => new Date().getFullYear();
  function garantir(d) {
    if (!d || d.calJan != null) return d;
    const P = d.pro, T0 = P && P.temporada, v0 = T0 && T0.vagas && T0.vagas[0];
    if (v0 && v0.dia) { d.calJan = (v0.dia | 0) - 27; d.calAno = anoHoje(); }                  // já na carreira: o 1º jogo é 28/01
    else if (P && P.presente) { d.calJan = (P.presenteDia | 0) - 7; d.calAno = anoHoje(); }     // já fez a peneira: ela foi em 08/01
    else { d.calJan = 1 - 30; d.calAno = anoHoje() - 2; }                                        // o passado: o dia 1 é 1º de fevereiro
    return d;
  }
  // a data de um dia do save: { dia (1–30), mes (1–12), ano, doAno (0–359), jan1 (o dia do save que é 1º de janeiro desse ano) }
  function data(d, dia) {
    garantir(d); dia = dia == null ? (d.dia || 1) : dia;
    const k = dia - d.calJan, a = Math.floor(k / 360), y = k - a * 360;
    return { dia: y % 30 + 1, mes: Math.floor(y / 30) + 1, ano: d.calAno + a, doAno: y, jan1: d.calJan + a * 360 };
  }
  const jan1 = (d, dia) => data(d, dia).jan1;
  // o dia do save de uma data (mes 1–12, diaMes 1–30) no ano que começa em j1
  const diaDe = (j1, mes, diaMes) => j1 + (mes - 1) * 30 + (diaMes - 1);
  // acerta o calendário para que o dia `dia` do save seja diaMes/mes/ano
  function acertar(d, dia, mes, diaMes, ano) { d.calJan = dia - ((mes - 1) * 30 + diaMes - 1); d.calAno = ano == null ? anoHoje() : ano; return d; }
  const tr = (s) => (typeof T === 'function' ? T(s) : s);
  const curto = (d, dia) => { const x = data(d, dia); return x.dia + ' ' + tr(CURTOS[x.mes - 1]); };                      // "14 mar"
  const longo = (d, dia) => { const x = data(d, dia); return (typeof Tf === 'function' ? Tf('{0} de {1}', x.dia, tr(MESES[x.mes - 1])) : x.dia + ' de ' + MESES[x.mes - 1]); };   // "14 de março"
  const nomeMes = (m) => tr(MESES[m - 1]);
  // "1 de dezembro de 2027" (o ano só aparece quando não é o ano de hoje, a não ser que sempreAno)
  const comAno = (d, dia, sempreAno) => { const x = data(d, dia), h = data(d); if (!sempreAno && x.ano === h.ano) return longo(d, dia);
    return typeof Tf === 'function' ? Tf('{0} de {1} de {2}', x.dia, tr(MESES[x.mes - 1]), x.ano) : x.dia + ' de ' + MESES[x.mes - 1] + ' de ' + x.ano; };
  return { MESES, CURTOS, garantir, data, jan1, diaDe, acertar, curto, longo, comAno, nomeMes };
})();

// ---------------------------------------------------------------------
// ATRIBUTOS DO JOGADOR — sistema separado para ser reaproveitado no modo história.
// Cada atributo vai de 1 a 10. O jogo "de sempre" (partida livre) usa 7 em TUDO: com 7 nada muda
// em relação ao que já existia (os valores originais de CONFIG são o "7"). Quanto menor o número,
// mais fraco o seu jogador, sempre por uma proporção (n / 7) elevada a um expoente:
//   chute / passe ... velocidade máxima da bola (a mínima continua igual)      expoente 0.9
//   efeito .......... quanto a bola faz de curva / sobe                         expoente 1.0
//   velocidade ...... andar e correr                                            expoente 0.35
//   resistência ..... segundos de corrida (e o tempo para encher é o inverso)   expoente 1.24
//   drible .......... tempo da tela do drible (e a recarga é o inverso)         expoente 0.5 / 0.8
//   domínio ......... tamanho da faixa verde do minigame de receber a bola      expoente 0.5
// Com 4 (jogador iniciante da história): 5 s de corrida e recupera 1 s de corrida a cada 1,5 s de descanso (barra cheia em 7,5 s).
// Uso:  Atributos.aplicar({ chute: 4, ... })  |  Atributos.aplicar(null) volta tudo para 7
//       Atributos.iniciante()  → objeto com tudo 4 (velocidade 5)     Atributos.fator('chute') → multiplicador atual
// ---------------------------------------------------------------------
const Atributos = (() => {
  // Os mesmos componentes das HABILIDADES de qualquer jogador (ver HABILIDADES logo abaixo). Os 7 antigos continuam
  // valendo do mesmo jeito; os novos, se não vierem, copiam o antigo mais parecido (força = chute, recuperação = resistência,
  // cruzamento = passe, finalização = chute), assim o personagem iniciante da história (tudo 4) continua igual.
  const NOMES = ['chute', 'passe', 'efeito', 'velocidade', 'resistencia', 'drible', 'dominio', 'forca', 'recuperacao', 'cruzamento', 'finalizacao', 'cabeceio', 'defesa', 'desarme', 'goleiro'];
  const CHAVES_BASE = ['USER_WALK', 'USER_RUN', 'USER_WALK_BALL', 'USER_RUN_BALL', 'STAMINA_RUN_TIME', 'STAMINA_REGEN_TIME', 'DRIBBLE_TIME', 'DRIBBLE_COOLDOWN'];
  const BASE = {}; for (const k of CHAVES_BASE) BASE[k] = CONFIG[k];
  const EXP = { chute: 0.9, passe: 0.9, efeito: 1, velocidade: 0.35, resistencia: 1.24, drible: 0.5, dominio: 0.5, forca: 0.9, recuperacao: 1.0, cruzamento: 0.9, finalizacao: 0.9, cabeceio: 0.8, defesa: 0.8, desarme: 0.8, goleiro: 0.8 };
  const COPIA = { forca: 'chute', recuperacao: 'resistencia', cruzamento: 'passe', finalizacao: 'chute' };
  const tudo = (n) => { const o = {}; for (const k of NOMES) o[k] = n; return o; };
  let atual = tudo(7);
  // (7.4.5) as habilidades de cada posição (as que começam mais altas no iniciante da história)
  const HAB_DA_POSICAO = {
    FWD: ['chute', 'finalizacao', 'velocidade', 'resistencia', 'efeito', 'drible', 'dominio'],
    MID: ['passe', 'cruzamento', 'resistencia', 'efeito', 'dominio', 'drible', 'recuperacao'],
    DEF: ['defesa', 'desarme', 'cabeceio', 'cruzamento', 'passe', 'forca', 'resistencia'],
    GK: ['goleiro', 'dominio', 'passe', 'forca', 'defesa', 'recuperacao'],
  };
  // (7.4.5) PISO DA HISTÓRIA: abaixo de 5 cada ponto pesa a METADE no jeito de jogar (3 joga como 4; 4 como 4,5). Os números do
  //   personagem continuam os de verdade (30, 40...): é só para o começo ficar fraco, mas jogável (correr, chutar e passar).
  const pisoHist = (n) => (n >= 5 ? n : 5 - (5 - n) * 0.5);
  // (6.2.0) CURVA DA HISTÓRIA para FORÇA, VELOCIDADE e RESISTÊNCIA (as três que a academia treina, de 5 a 10). O personagem da
  //   história (marcado por _corridaSeg, o fôlego do iniciante) começa em 5 e cada ponto a mais rende MENOS que o anterior:
  //   ganho(n) = 1 − (1 − k)^1,5, com k = (n − 5) / 5. O 5 é exatamente o jogo de antes (nada piora); no 10:
  //     velocidade → conta como 8,5 (corre como um bom jogador do nível difícil, ~+7% sobre o 7 da partida livre, não um foguete)
  //     força      → conta como 8,5 no chute/passe longo (+~8% de velocidade máxima de chute sobre o 5) e o bote do adversário
  //                  acerta ~26% menos (Atributos.posse(): 1 → 1,35)
  //     resistência → 9 s de corrida com a barra cheia (o iniciante tem 5 s; a partida livre tem 10 s com tudo 7)
  //   A partida livre (sem _corridaSeg) continua igual: tudo 7, sem curva.
  let posseK = 1, entrada = {};
  const ganhoHist = (n) => { const k = Math.max(0, Math.min(1, ((+n || 5) - 5) / 5)); return 1 - Math.pow(1 - k, 1.5); };
  const efetivoHist = (n) => ((+n || 5) <= 5 ? (+n || 5) : 5 + 3.5 * ganhoHist(n));
  const razao = (nome) => Math.pow(clampA((atual[nome] ?? 7) / 7, 0.15, 1.6), EXP[nome] ?? 1);
  function clampA(v, a, b) { return Math.max(a, Math.min(b, v)); }
  function aplicar(attrs) {
    const a = Object.assign({}, attrs || {});
    for (const [novo, velho] of Object.entries(COPIA)) if (a[novo] == null && a[velho] != null) a[novo] = a[velho];
    atual = Object.assign(tudo(7), a); entrada = Object.assign({}, atual);   // entrada: os números como vieram (antes da curva)
    const hist = a._corridaSeg > 0;                                       // (6.2.0) personagem da história: curva de 5 a 10
    posseK = hist ? 1 + 0.35 * ganhoHist(a.forca) : 1;
    if (hist) for (const n of NOMES) atual[n] = pisoHist(+atual[n] || 5);
    if (hist) for (const n of ['velocidade', 'forca']) atual[n] = efetivoHist(atual[n]);
    const vel = razao('velocidade'), res = razao('resistencia'), dri = razao('drible');
    CONFIG.USER_WALK = BASE.USER_WALK * vel; CONFIG.USER_RUN = BASE.USER_RUN * vel;
    CONFIG.USER_WALK_BALL = BASE.USER_WALK_BALL * vel; CONFIG.USER_RUN_BALL = BASE.USER_RUN_BALL * vel;
    // (7.4.15) o fôlego soma segundos (antes multiplicava); (7.4.16) GRADUAL na escala toda: cada ponto vale ~0,56 s, do 1 (0 s) ao 10 (+5 s)
    CONFIG.STAMINA_RUN_TIME = BASE.STAMINA_RUN_TIME * Math.min(1, res) + 5 * clampA(((+atual.resistencia || 7) - 1) / 9, 0, 1);
    CONFIG.STAMINA_REGEN_TIME = BASE.STAMINA_REGEN_TIME / razao('recuperacao');   // encher a barra: recuperação
    // Ajuste fino do fôlego (iniciante): _corridaSeg = segundos de corrida; _recuperaCada = segundos de descanso para devolver 1 s de corrida.
    if (a._corridaSeg > 0) CONFIG.STAMINA_RUN_TIME = a._corridaSeg + 5 * ganhoHist(a.resistencia);   // (6.2.0) 5 s no 5 → (7.4.15) 10 s no 10 (+ os 3 s de CORRIDA_EXTRA na partida; 6 até a 7.4.16)
    if (a._recuperaCada > 0) CONFIG.STAMINA_REGEN_TIME = CONFIG.STAMINA_RUN_TIME * a._recuperaCada / (1 + 0.5 * ganhoHist(a.recuperacao));   // (7.1.14) a RECUPERAÇÃO vale na história: no 10 enche 1,5x mais rápido
    CONFIG.DRIBBLE_TIME = BASE.DRIBBLE_TIME * dri;
    CONFIG.DRIBBLE_COOLDOWN = BASE.DRIBBLE_COOLDOWN / Math.pow(clampA(atual.drible / 7, 0.15, 1.6), 0.8);
  }
  return {
    NOMES, aplicar,
    padrao: () => tudo(7),
    // (7.4.5) o INICIANTE da história: tudo 3 (30 na régua de 0 a 100, a mesma dos times: várzea 30–60, Série B 50–70, Série A 65–85)
    //   e as habilidades da posição escolhida no começo do modo história sorteadas entre 4,0 e 5,0 (40 a 50). Sem posição (o treino
    //   do tutorial, antes da escolha): tudo 5, como antes. O fôlego curto do iniciante continua.
    iniciante: (pos) => {
      const ini = { _corridaSeg: 5, _recuperaCada: 1.5 };
      if (!HAB_DA_POSICAO[pos]) return Object.assign(tudo(5), ini);
      const o = Object.assign(tudo(3), ini, { _ini: pos });
      for (const n of HAB_DA_POSICAO[pos]) o[n] = Math.round((4 + Math.random()) * 10) / 10;
      return o;
    },
    HAB_DA_POSICAO: () => HAB_DA_POSICAO,
    valor: (nome) => atual[nome],
    fator: (nome) => razao(nome),
    posse: () => posseK,                                                  // (6.2.0) divide a chance do bote do adversário em você (força)
    efetivoHist, ganhoHist,
    get atual() { return Object.assign({}, atual); },
    get entrada() { return Object.assign({}, entrada); },               // (6.2.0) sem a curva da história (para reaplicar com ajustes)
  };
})();

// ---------------------------------------------------------------------
// HABILIDADES — componentes de CADA jogador (a IA dos dois times e você). Cada uma vai de 1 a 10 e 7 é o jogo de
// antes (nada muda). hab(p, nome) devolve o número; fh(p, nome) devolve o multiplicador (n / 7)^expoente.
//   defesa ......... leitura de jogo sem a bola: reação para cortar passe, bote na hora certa, marcar colado
//   desarme ........ chance do bote/carrinho pegar a bola (e de não fazer falta)
//   forca .......... velocidade máxima de chute, passe longo, cabeçada e chutão
//   resistencia .... quanto tempo corre até cansar          recuperacao ... quanto tempo para recuperar o fôlego
//   velocidade ..... andar e correr                          chute ......... qualidade (mira) do chute
//   efeito ......... curva/subida que a bola faz             passe ......... precisão do passe
//   cruzamento ..... precisão do cruzamento e da bola longa  drible ........ chance de tentar e de passar no drible
//   dominio ........ dominar bola forte/alta sem deixar escapar
//   cabeceio ....... cabeçada (força, mira) e escolher entre cabecear e matar no peito
//   finalizacao .... mira e frieza dentro/perto da área      goleiro ....... defesas, alcance do mergulho, saída
// Partidas comuns: a IA ADVERSÁRIA nasce com valores da faixa do nível (muito fácil 2–3, fácil 3–4, normal 5–6, difícil 6–8,
// muito difícil 8–10) e os SEUS companheiros com 5–6. Cada jogador tem um "perfil" fixo (pela semente dele): uns finalizam
// melhor, outros marcam melhor; a posição puxa um pouco (zagueiro: defesa/desarme/cabeceio; atacante: finalização/chute;
// meio: passe/drible; goleiro: goleiro). O seu jogador usa os Atributos (história) — na partida livre, tudo 7.
