const BANDEIRAS = [];

// Placas de publicidade em volta do campo. Os "anúncios" são dos seus próprios projetos.
// placas do estádio da Série B: o comércio do bairro (o último é escuro: as faces de cima e das pontas usam um pedaço dele)
const ANUNCIOS_B = [['PADARIA PÃO QUENTINHO', '#e8c27a', '#5a2a10'], ['AUTO PEÇAS 2 IRMÃOS', '#1f4a8a', '#f2c230'], ['AÇOUGUE BOI GORDO', '#a8201a', '#ffffff'],
  ['FUTEBOL JS', '#F7941D', '#071430'], ['MATERIAIS SÃO JORGE', '#2f7a3a', '#ffffff'], ['BAR DO TIÃO', '#111111', '#f2c230']];
// placas da Série A (LED): marcas grandes de mentira e os projetos de sempre
const ANUNCIOS_A = [['BANCO FAKES', '#101820', '#2fe08a'], ['FUTEBOL JS', '#F7941D', '#071430'], ['TV AGRICULTURA', '#0d3b1e', '#f2c230'], ['SUPER LAN MASTER', '#0B4F9C', '#ffffff'],
  ['GOLAÇO ESPORTES', '#c8202e', '#ffffff'], ['ORBIT', '#071430', '#6bf08e'], ['ESFERA', '#1d2a6b', '#ffffff'], ['CACHOLA', '#111111', '#6bf08e']];
let ESTADIO_A = null;                              // o último estádio da Série A montado ({ modelo, nome, torcedores })
// (7.4.19) TEXTO QUE CABE: diminui a FONTE até o texto caber na largura (antes o canvas espremia o texto na marra, com o maxWidth,
//   e nome de time grande ficava achatado/"bugado"; no túnel ainda era cortado em 22 letras). Desenha e devolve o tamanho usado.
function textoQueCabe(g, txt, x, y, maxW, px, op) {
  op = op || {};
  const peso = op.peso || 'bold', fam = op.familia || 'Arial', min = op.min || Math.max(6, Math.round(px * 0.4));
  let t = px; g.font = peso + ' ' + t + 'px ' + fam;
  while (t > min && g.measureText(txt).width > maxW) { t -= 1; g.font = peso + ' ' + t + 'px ' + fam; }
  g.fillText(txt, x, y, maxW);                    // (só no limite mínimo ainda aperta um pouco)
  return t;
}
function buildBoards(lista) {
  const ADS = lista || [['SUPER LAN MASTER', '#0B4F9C', '#F7941D'], ['FUTEBOL JS', '#F7941D', '#071430'], ['PONTO COMUNITÁRIO', '#1f9e5c', '#ffffff'],
    ['ATALIBA', '#d8443a', '#ffffff'], ['ORBIT', '#071430', '#6bf08e'], ['CACHOLA', '#111111', '#6bf08e']];
  const tex = drawTexture(256, 16, (g) => {
    const w = 256 / ADS.length;
    ADS.forEach(([txt, bg, fg], i) => {
      g.fillStyle = bg; g.fillRect(i * w, 0, w, 16);
      g.fillStyle = fg; g.textAlign = 'center'; g.textBaseline = 'middle';
      textoQueCabe(g, txt, i * w + w / 2, 8.5, w - 4, 8);
    });
  }, 1, 1);
  const H = 0.9;
  // DESEMPENHO: antes cada placa tinha um material por face (6 chamadas de desenho); agora é 1.
  // As faces de cima e das pontas usam um pedacinho escuro do próprio anúncio.
  const add = (len, x, z, alongX) => {
    const t = tex.clone(); t.needsUpdate = true; t.repeat.set(Math.max(1, Math.round(len / 34)), 1); t.wrapS = THREE.RepeatWrapping;
    const m = new THREE.MeshLambertMaterial({ map: t });
    const L = new Lote();
    const frente = alongX ? [4, 5] : [0, 1];
    const rr = t.repeat.x, escuro = [0.92 / rr, 0.1, 0.93 / rr, 0.2];   // pedaço preto (anúncio CACHOLA), já contando a repetição
    L.caixa(alongX ? len : 0.2, H, alongX ? 0.2 : len, 0xffffff, 0, 0, 0, (i) => (frente.includes(i) ? [0, 0, 1, 1] : escuro));
    const mesh = L.malha(m);
    mesh.position.set(x, H / 2, z);
    ESTADIO.add(mesh); freeze(mesh);
    return mesh;
  };
  // a placa do lado dos bancos vai em três pedaços: o do meio sai do lugar quando os times entram pelo túnel (mostrarTunel)
  const G2 = TUNEL_LARG / 2 + 0.2;
  add(BOARD_X - G2, -(BOARD_X + G2) / 2, -BOARD_ZN, true);
  TUNEL.placa = add(G2 * 2, 0, -BOARD_ZN, true);
  add(BOARD_X - G2, (BOARD_X + G2) / 2, -BOARD_ZN, true);
  add(BOARD_X * 2, 0, BOARD_Z, true);
  add(BOARD_Z + BOARD_ZN, -BOARD_X, (BOARD_Z - BOARD_ZN) / 2, false);
  add(BOARD_Z + BOARD_ZN, BOARD_X, (BOARD_Z - BOARD_ZN) / 2, false);
}
// O TÚNEL DA ENTRADA DOS TIMES: o túnel inflável nas cores do mandante (com o escudo e o nome dos lados), do meio da linha lateral
//   dos bancos até dentro da arquibancada. Fica escondido no jogo; mostrarTunel(true) o põe no lugar e tira a placa do meio
//   (a cena de entrada da partida livre). Os times saem pela boca dele, a TUNEL_BOCA metros da linha lateral.
const TUNEL_LARG = 3.4, TUNEL_BOCA = 2.9;
const TUNEL = { placa: null, grupo: null };
function montarTunel() {
  TUNEL.grupo = null;
  const P = PARTIDA; if (!P) return;
  const casa = P.mandante === 1 ? 1 : 0, U = P.uniformes[casa], T = P.timesObj[casa];
  const c1 = hexNum(U.camisa), c2raw = hexNum(U.listra && U.listra !== U.camisa ? U.listra : U.gola || '#f2f2ee');
  const lum = (c) => ((c >> 16) & 255) * 0.3 + ((c >> 8) & 255) * 0.59 + (c & 255) * 0.11;
  const c2 = Math.abs(lum(c1) - lum(c2raw)) < 40 ? (lum(c1) > 128 ? 0x1b1d22 : 0xf2f2ee) : c2raw;
  // o fundo: logo depois da placa, sem entrar na arquibancada (a frente dela no meio do lado dos bancos vem do estadiosA.js)
  const frente = ESTADIO_A && window.EstadiosA && EstadiosA.atual && EstadiosA.atual() ? EstadiosA.atual().frenteZ : null;
  let fundo = BOARD_ZN + 1.6; if (frente) fundo = Math.max(BOARD_ZN + 0.5, Math.min(fundo, frente - 0.3));
  const z0 = -(HALF_W + TUNEL_BOCA), z1 = -fundo, W = TUNEL_LARG / 2, YL = 1.55, RY = 1.2, NA = 7, PASSO = 1.5;
  TUNEL.fundoZ = z1;
  // a seção: as duas paredes retas e o arco de cima (pontos de baixo à esquerda, pelo alto, até baixo à direita)
  const S = [[-W, 0]]; for (let k = 0; k <= NA; k++) { const a = Math.PI - Math.PI * k / NA; S.push([W * Math.cos(a), YL + RY * Math.sin(a)]); } S.push([W, 0]);
  const L = new Lote(), quad = (A, B, C, D, cor, nx, ny, nz) => {
    const base = L.pos.length / 3, r = ((cor >> 16) & 255) / 255, g = ((cor >> 8) & 255) / 255, b = (cor & 255) / 255;
    for (const q of [A, B, C, D]) { L.pos.push(q[0], q[1], q[2]); L.nor.push(nx, ny, nz); L.uv.push(0.3, 0.6); L.cor.push(r, g, b); }
    L.idx.push(base, base + 1, base + 2, base, base + 2, base + 3);
  };
  const dentro = misturarCor(c1, 0x000000, 0.72), dentro2 = misturarCor(c2, 0x000000, 0.75);
  for (let z = z0, k = 0; z > z1 + 0.01; z -= PASSO, k++) {
    const za = z, zb = Math.max(z1, z - PASSO), anel = k % 2 === 0;
    for (let i = 0; i < S.length - 1; i++) {
      const [xa, ya] = S[i], [xb, yb] = S[i + 1];
      let nx = -(yb - ya), ny = xb - xa; const nl = Math.hypot(nx, ny) || 1; nx /= nl; ny /= nl;   // a normal para fora do túnel
      const corF = anel ? c1 : (i === 0 || i === S.length - 2 ? c1 : c2), corD = anel ? dentro : dentro2;
      quad([xa, ya, za], [xb, yb, za], [xb, yb, zb], [xa, ya, zb], corF, nx, ny, 0);       // por fora
      quad([xa, ya, za], [xa, ya, zb], [xb, yb, zb], [xb, yb, za], corD, -nx, -ny, 0);     // por dentro (escuro)
    }
  }
  // o fundo fechado (escuro): de dentro não se vê a arquibancada nem quem ainda está esperando
  for (let i = 0; i < S.length - 1; i++) { const [xa, ya] = S[i], [xb, yb] = S[i + 1]; quad([xb, yb, z1], [xa, ya, z1], [0, YL * 0.5, z1], [0, YL * 0.5, z1], 0x0c0d10, 0, 0, 1); }
  // a boca: um anel mais gordo (a moldura) na ponta do campo, com a frente e o contorno
  const esp = 0.28, borda = c1, filete = c2;
  for (let i = 0; i < S.length - 1; i++) {
    const [xa, ya] = S[i], [xb, yb] = S[i + 1];
    const out = (x, y) => { const d = Math.hypot(x, y - YL * 0.5) || 1; return [x + (x / d) * esp, y + ((y - YL * 0.5) / d) * esp]; };
    const [xa2, ya2] = i === 0 ? [xa - esp, 0] : out(xa, ya), [xb2, yb2] = i === S.length - 2 ? [xb + esp, 0] : out(xb, yb);
    quad([xa, ya, z0], [xb, yb, z0], [xb2, yb2, z0], [xa2, ya2, z0], borda, 0, 0, 1);
    // o filete na cor 2, no meio da moldura
    const fa = [xa + (xa2 - xa) * 0.4, ya + (ya2 - ya) * 0.4], fb = [xb + (xb2 - xb) * 0.4, yb + (yb2 - yb) * 0.4], ga = [xa + (xa2 - xa) * 0.62, ya + (ya2 - ya) * 0.62], gb = [xb + (xb2 - xb) * 0.62, yb + (yb2 - yb) * 0.62];
    quad([fa[0], fa[1], z0 + 0.01], [fb[0], fb[1], z0 + 0.01], [gb[0], gb[1], z0 + 0.01], [ga[0], ga[1], z0 + 0.01], filete, 0, 0, 1);
    quad([xa2, ya2, z0], [xb2, yb2, z0], [xb2, yb2, z0 - 0.5], [xa2, ya2, z0 - 0.5], borda, (xa2 + xb2) / 2 / (W + esp), Math.max(0, (ya2 + yb2) / 2 - YL) / RY, 0);
  }
  const grupo = new THREE.Group(); grupo.name = 'tunel';
  const corpo = L.malha(MAT_CORES); grupo.add(corpo);
  // a faixa dos lados: o escudo e o nome do mandante, repetidos
  const nome = String(T.nome || '').toUpperCase(), emb = T.emblema;
  const tex = drawTexture(256, 32, (g) => {
    g.fillStyle = '#' + c1.toString(16).padStart(6, '0'); g.fillRect(0, 0, 256, 32);
    try { desenharEmblema(g, 6, 3, 24, 26, emb); } catch (e) { /* sem escudo */ }
    g.fillStyle = '#' + c2.toString(16).padStart(6, '0'); g.textAlign = 'left'; g.textBaseline = 'middle';
    textoQueCabe(g, nome, 36, 17, 214, 15);        // (7.4.19) nome inteiro, com a fonte menor se precisar
  });
  tex.wrapS = THREE.RepeatWrapping; const comp = Math.abs(z1 - z0); tex.repeat.set(Math.max(1, Math.round(comp / 6)), 1);
  const matF = new THREE.MeshLambertMaterial({ map: tex });
  for (const s of [-1, 1]) {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(comp, 0.75), matF);
    m.position.set(s * (W + 0.025), 1.0, (z0 + z1) / 2); m.rotation.y = s * Math.PI / 2;
    grupo.add(m);
  }
  grupo.visible = false;
  ESTADIO.add(grupo);
  TUNEL.grupo = grupo;
}
function mostrarTunel(on) {
  if (TUNEL.grupo) TUNEL.grupo.visible = !!on;
  if (TUNEL.placa) TUNEL.placa.visible = !on;
}

// ---------------------------------------------------------------------
// TORCIDA: cada torcedor é um retângulo com uma textura transparente (sprite), sentado ou
// em pé numa arquibancada de degraus. São 4 tipos — sentado/em pé × camisa azul/vermelha — cada
// um em 3 tons de pele e virado para um lado ou outro (espelhado), então ninguém parece clone.
// DESEMPENHO: os ~9 mil torcedores ficam numa malha só (1 chamada de desenho, sem transparência
// "de verdade": o fundo é cortado com alphaTest, que é barato). O sobe-e-desce é calculado na
// PLACA DE VÍDEO (vertex shader): o processador só atualiza 3 números por quadro.
//   - normal: quem está em pé balança, quem está sentado mexe pouquinho
//   - gol: a torcida do time que marcou pula alta por ~7 s (a do outro time quase para)
//   - "ola": de vez em quando uma onda dá a volta no estádio
// ---------------------------------------------------------------------
const ARQ = { FILEIRAS: 18, ALT0: 1.0, DEGRAU_Y: 0.62, DEGRAU_Z: 1.0, DIST0: 13 };   // degraus da arquibancada
const crowd = (() => {
  // Atlas 128×64: 12 células de 16×32 px. Célula = (emPe × 6) + (time × 3) + pele.
  // Cores das camisas da torcida = cores dos dois times da partida (pintarAtlas troca).
  let CAMISAS = [['#0B4F9C', '#083a73'], ['#C8352B', '#8f241d']];
  const PELES_T = ['#F2C9A5', '#BF8159', '#62402A'];
  const CABELOS_T = ['#1C140F', '#6B4423', '#0E0E0E'];
  const desenharAtlas = (g) => {
    g.clearRect(0, 0, 128, 64);
    for (let i = 0; i < 12; i++) {
      const ox = (i % 8) * 16, oy = Math.floor(i / 8) * 32;
      const emPe = i >= 6, time = Math.floor(i / 3) % 2, pl = i % 3;
      const [cam, esc] = CAMISAS[time], pele = PELES_T[pl], cab = CABELOS_T[pl];
      const r = (x, y, w, h, c) => { g.fillStyle = c; g.fillRect(ox + x, oy + y, w, h); };
      if (emPe) {
        // Em pé, braços para cima (torcendo).
        r(5, 1, 6, 2, cab); r(5, 3, 6, 6, pele); r(6, 5, 1, 1, '#16120F'); r(9, 5, 1, 1, '#16120F');
        r(7, 9, 2, 1, pele);
        r(2, 2, 2, 6, pele); r(12, 2, 2, 6, pele);           // braços levantados
        r(2, 8, 2, 3, cam); r(12, 8, 2, 3, cam);              // mangas
        r(4, 10, 8, 7, cam); r(4, 17, 8, 2, esc);             // camisa
        r(4, 19, 8, 3, '#2a3550'); r(4, 22, 3, 7, '#2a3550'); r(9, 22, 3, 7, '#2a3550');   // calça
        r(4, 29, 3, 2, '#141414'); r(9, 29, 3, 2, '#141414');                              // tênis
      } else {
        // Sentado: só aparece da coxa para cima (as pernas ficam atrás do degrau da frente).
        r(5, 11, 6, 2, cab); r(5, 13, 6, 6, pele); r(6, 15, 1, 1, '#16120F'); r(9, 15, 1, 1, '#16120F');
        r(7, 19, 2, 1, pele);
        r(2, 20, 2, 3, cam); r(12, 20, 2, 3, cam); r(2, 23, 2, 4, pele); r(12, 23, 2, 4, pele);
        r(4, 20, 8, 6, cam); r(4, 26, 8, 2, esc);
        r(3, 28, 10, 4, '#2a3550');                           // joelhos/coxas
      }
    }
  };
  const tex = drawTexture(128, 64, desenharAtlas);
  tex.minFilter = THREE.NearestMipmapLinearFilter; tex.generateMipmaps = true;   // de longe não "pisca"

  // uFase: a "fase" do pula-pula de cada torcida, somada AQUI (no processador) quadro a quadro.
  // Antes o shader fazia sin(tempo × velocidade); quando a velocidade mudava (gol), o tempo
  // já estava grande e a fase dava saltos enormes — a torcida "acelerava" e embaralhava.
  const U = { uFase: { value: new THREE.Vector2(0, 0) }, uFesta: { value: new THREE.Vector2(0, 0) }, uOla: { value: -1 } };
  const material = new THREE.MeshLambertMaterial({ map: tex, alphaTest: 0.4, side: THREE.DoubleSide });
  material.onBeforeCompile = (sh) => {
    Object.assign(sh.uniforms, U);
    sh.vertexShader = 'attribute float aFase;\nattribute vec3 aJeito;\nuniform vec2 uFase;\nuniform vec2 uFesta;\nuniform float uOla;\n' +
      sh.vertexShader.replace('#include <begin_vertex>', `#include <begin_vertex>
        // aJeito: x = time (0 azul, 1 vermelho), y = em pé (1) ou sentado (0), z = posição na volta do estádio (0 a 1)
        float festa = aJeito.x < 0.5 ? uFesta.x : uFesta.y;
        float outro = aJeito.x < 0.5 ? uFesta.y : uFesta.x;
        float fase = aJeito.x < 0.5 ? uFase.x : uFase.y;
        float onda = max(0.0, sin(fase + aFase * 6.2832));
        float amp = mix(aJeito.y > 0.5 ? 0.09 : 0.02, aJeito.y > 0.5 ? 0.6 : 0.45, festa) * (1.0 - 0.8 * outro);
        float dOla = abs(fract(aJeito.z - uOla + 0.5) - 0.5);          // distância até a onda (dá a volta)
        float ola = uOla < 0.0 ? 0.0 : exp(-dOla * dOla * 1600.0) * 0.7;
        transformed.y += onda * amp + ola;`);
  };

  // Pinta (só posições). As fileiras são montadas em buildStands.
  const pos = [], nor = [], uv = [], fase = [], jeito = [], idx = [];
  const W = 0.8, H = 1.6, IN = 0.5 / 128, INV = 0.5 / 64;   // meio texel de margem
  // base: pé do torcedor; dir: direção em que ele OLHA (para o campo); ang: 0..1 na volta do estádio
  function torcedor(bx, by, bz, dirX, dirZ, time, emPe, ang) {
    cont[time ? 1 : 0]++;                                // (7.4.9) quantos de cada time (o tamanho e o volume de cada torcida)
    const cel = (emPe ? 6 : 0) + time * 3 + (Math.random() * 3 | 0);
    let u0 = (cel % 8) * 16 / 128 + IN, u1 = ((cel % 8) * 16 + 16) / 128 - IN;
    const vT = 1 - Math.floor(cel / 8) * 32 / 64 - INV, vB = 1 - (Math.floor(cel / 8) * 32 + 32) / 64 + INV;
    if (Math.random() < 0.5) [u0, u1] = [u1, u0];   // espelhado
    // "Direita" de quem olha para ele vindo do campo = (−dz, 0, dx) da direção do olhar dele invertida.
    const rx = dirZ * W / 2, rz = -dirX * W / 2;
    const y0 = by - (emPe ? 0 : 0.05), y1 = y0 + H;
    const b = pos.length / 3;
    pos.push(bx - rx, y1, bz - rz, bx + rx, y1, bz + rz, bx - rx, y0, bz - rz, bx + rx, y0, bz + rz);
    for (let i = 0; i < 4; i++) { nor.push(dirX, 0, dirZ); jeito.push(time, emPe ? 1 : 0, ang); }
    uv.push(u0, vT, u1, vT, u0, vB, u1, vB);
    const f = Math.random(); fase.push(f, f, f, f);
    idx.push(b, b + 2, b + 1, b + 2, b + 3, b + 1);
  }
  function malha() {
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setAttribute('normal', new THREE.Float32BufferAttribute(nor, 3));
    g.setAttribute('uv', new THREE.Float32BufferAttribute(uv, 2));
    g.setAttribute('aFase', new THREE.Float32BufferAttribute(fase, 1));
    g.setAttribute('aJeito', new THREE.Float32BufferAttribute(jeito, 3));
    g.setIndex(idx);
    return new THREE.Mesh(g, material);
  }

  let festa = [0, 0], olaT = -1, proximaOla = rand(35, 70);
  const cont = [0, 0], canto = [0, 0];               // (7.4.9) torcedores de cada time; canto = segundos que cada torcida ainda canta (pula no ritmo)
  // Chamado todo quadro pelo loop (só mexe em 3 uniforms).
  const DOIS_PI = Math.PI * 2;
  function atualizar(dt) {
    festa = festa.map((f) => Math.max(0, f - dt / 7));
    for (let t = 0; t < 2; t++) if (canto[t] > 0) { canto[t] -= dt; festa[t] = Math.max(festa[t], 0.34); }   // (7.4.9) cantando: pula no ritmo
    // A festa SEGURA enquanto o jogo está no gol/comemoração/replay; só começa a baixar
    // quando todo mundo volta para o meio (saída de bola).
    if ((G.state === 'goal' || G.state === 'celebrate' || G.state === 'replay') && G.scoredBy >= 0) festa[G.scoredBy] = 1;
    const f0 = Math.min(1, festa[0] * 1.6), f1 = Math.min(1, festa[1] * 1.6);   // segura no máximo e depois cai
    U.uFesta.value.set(f0, f1);
    // Velocidade (rad/s) de cada torcida: 5 normal, até 10 na festa. Soma e dá a volta em 2π.
    U.uFase.value.set((U.uFase.value.x + dt * (5 + 5 * f0)) % DOIS_PI, (U.uFase.value.y + dt * (5 + 5 * f1)) % DOIS_PI);
    if (olaT >= 0) { olaT += dt / 11; if (olaT > 1) { olaT = -1; proximaOla = rand(45, 90); } }
    else if (G.state === 'play' && (proximaOla -= dt) <= 0) olaT = 0;
    U.uOla.value = olaT;
  }
  // Gol: a torcida desse time explode (e para a ola, se tiver).
  function comemorar(time) { festa[time] = 1; festa[1 - time] = Math.min(festa[1 - time], 0.2); olaT = -1; proximaOla = rand(45, 90); }
  // Nova partida: cores dos times (escurece um pouco para a parte de baixo da camisa).
  function pintarAtlas(cor0, cor1) {
    const esc = (h) => { const n = parseInt(h.slice(1), 16), k = 0.7; return '#' + [16, 8, 0].map((sh) => Math.round(((n >> sh) & 255) * k).toString(16).padStart(2, '0')).join(''); };
    CAMISAS = [[cor0, esc(cor0)], [cor1, esc(cor1)]];
    const g = tex.image.getContext('2d');
    desenharAtlas(g);
    tex.needsUpdate = true;
  }
  // Nova partida: esvazia a lista de torcedores (buildStands monta de novo).
  function limpar() { pos.length = nor.length = uv.length = fase.length = jeito.length = idx.length = 0; festa = [0, 0]; cont[0] = cont[1] = 0; canto[0] = canto[1] = 0; }
  // (7.4.9) a torcida reage: agitar = um pulinho (olé, defesa, palmas); cantar = pula no ritmo enquanto canta;
  //   parte(t) = fração da torcida que é do time t; lotacao() = 0..1 (estádio vazio → cheio), para o volume do som
  function agitar(time, v) { festa[time] = Math.max(festa[time], v); }
  function cantar(time, dur) { canto[time] = Math.max(canto[time], dur); }
  function parte(time) { const n = cont[0] + cont[1]; return n ? cont[time] / n : 0.5; }
  function lotacao() { return clamp((cont[0] + cont[1]) / 1400, 0.12, 1); }
  return { torcedor, malha, atualizar, comemorar, pintarAtlas, limpar, agitar, cantar, parte, lotacao, total: () => cont[0] + cont[1] };
})();

// ---------------------------------------------------------------------
// SONS — todos GERADOS no código com a Web Audio API: nenhum arquivo para baixar.
// Cada som é uma "receita" de osciladores (tons) e ruído filtrado:
//   chute ........ "tum" grave (tom que cai rápido) + estalo de ruído; mais forte = mais alto
//   toque ........ o mesmo, curtinho e baixo (passe, domínio, bola chegando no pé)
//   apito ........ tom agudo (~2,8 kHz) com "tremido" de ~32 Hz (a bolinha do apito)
//   torcida ...... ruído filtrado em loop, sempre tocando baixinho; sobe com a bola perto do gol
//   gol .......... a torcida sobe e fica alta e constante uns 6 s (ruído + "vozes": vários tons
//                  desafinados juntos fazendo um "uôôô")
//   trave ........ "plém" metálico (tons não harmônicos)
//   óóh .......... chute para fora: vozes caindo de decepção
//   passos ....... "chhk" baixinho na grama, só você correndo
//   defesa ....... "pof" abafado das luvas + um "uuuh" curto da torcida
//   clique ....... bipes de interface (domínio e drible); domínio perfeito = arpejo
//   drible ....... "fuuu" (ruído varrendo de grave para agudo)
// DESEMPENHO: um único AudioContext, ruído criado UMA vez (2 s) e reaproveitado, no máximo
// 14 sons curtos tocando juntos. No celular o som só liga depois de um toque (botão JOGAR).
// ---------------------------------------------------------------------
const Som = (() => {
  let ctx = null, mestre = null, ruido = null, mudo = false, vozes = 0, golAtivo = null;
  let torcidaGain = null, torcidaFiltro = null, nivelAtual = -1;
  try { mudo = localStorage.getItem('futebolJsMudo') === '1'; } catch (e) { /* sem armazenamento */ }
  // (7.4.13) VOLUME POR CATEGORIA (Configurações): geral, efeitos (bola, apito, cliques e os sons das fases), torcida (o fundo,
  //   o grito do gol, palmas, vaia, batuque), música (o tema do menu e as músicas das fases) e vozes (a fala dos personagens).
  //   Cada uma tem o seu volume (0 a 1) e o seu "mudo"; fica guardado no aparelho (futebolJs.volumes.v1).
  const CATS = ['geral', 'efeitos', 'torcida', 'musica', 'vozes'];
  const VOL = { geral: 1, efeitos: 1, torcida: 1, musica: 1, vozes: 1 }, MUDO = { geral: false, efeitos: false, torcida: false, musica: false, vozes: false };
  try { const v = JSON.parse(localStorage.getItem('futebolJs.volumes.v1') || 'null'); if (v) for (const c of CATS) { if (v.vol && Number.isFinite(v.vol[c])) VOL[c] = clamp(v.vol[c], 0, 1); if (v.mudo) MUDO[c] = !!v.mudo[c]; } } catch (e) { /* sem armazenamento */ }
  const bus = {};                                          // efeitos, torcida, musica, vozes → mestre
  const nivelDe = (c) => (MUDO[c] ? 0 : VOL[c]);
  const nivelMestre = () => (mudo || MUDO.geral ? 0 : 0.85 * VOL.geral);
  function aplicarVolumes() {
    if (!ctx) return;
    const t = ctx.currentTime;
    if (mestre) mestre.gain.setTargetAtTime(nivelMestre(), t, 0.05);
    for (const c of CATS) if (bus[c]) bus[c].gain.setTargetAtTime(nivelDe(c), t, 0.05);
  }
  function guardarVolumes() { try { localStorage.setItem('futebolJs.volumes.v1', JSON.stringify({ vol: VOL, mudo: MUDO })); } catch (e) { /* ok */ } }

  function ligar() {
    try {
      if (!ctx) {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return;
        ctx = new AC();
        const comp = ctx.createDynamicsCompressor();          // evita estourar quando soma tudo
        mestre = ctx.createGain(); mestre.gain.value = nivelMestre();
        mestre.connect(comp); comp.connect(ctx.destination);
        for (const c of CATS) { if (c === 'geral') continue; bus[c] = ctx.createGain(); bus[c].gain.value = nivelDe(c); bus[c].connect(mestre); }
        ruido = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
        const d = ruido.getChannelData(0);
        for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
        montarPalmas(); montarBateria();
        montarTorcida();
      }
      // (7.4.11) acorda de 'suspended' e também de 'interrupted' (o Safari do iPhone interrompe o áudio numa ligação, num
      //   alarme, ao trocar de app...). Fechado de vez: monta outro.
      if (ctx.state === 'closed') { ctx = null; vozes = 0; golAtivo = null; nivelAtual = -1; return ligar(); }
      if (ctx.state !== 'running') { const p = ctx.resume(); if (p && p.catch) p.catch(() => {}); }
    } catch (e) { ctx = null; }
  }
  // (7.4.11) só toca com o áudio RODANDO: parado ('suspended'/'interrupted') o relógio do áudio congela e tudo o que fosse
  //   agendado tocaria junto quando ele voltasse — um estouro de sons sobrepostos (o chiado) que às vezes travava o som de vez
  const pronto = () => ctx && ctx.state === 'running' && !mudo && G.state !== 'paused';
  // Limite de sons curtos ao mesmo tempo (cada um se "desconta" quando termina).
  function vaga(dur) {
    if (vozes >= 14) return false;
    vozes++; setTimeout(() => { vozes--; }, dur * 1000 + 50);
    return true;
  }
  // Envelope: sobe até "pico" em "ataque" segundos e some até "dur".
  function env(g, t0, ataque, pico, dur) {
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0002, pico), t0 + ataque);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
  }
  function fonteRuido(t0, dur, loop) {
    const s = ctx.createBufferSource(); s.buffer = ruido; s.loop = !!loop;
    s.start(t0, Math.random() * 1.5);
    if (!loop) s.stop(t0 + dur + 0.05);
    return s;
  }
  function filtro(tipo, freq, Q) { const f = ctx.createBiquadFilter(); f.type = tipo; f.frequency.value = freq; f.Q.value = Q || 0.7; return f; }
  function ganho() { return ctx.createGain(); }
  // Tom com a frequência caindo de f0 para f1 (chute, toque, defesa).
  function tom(tipo, f0, f1, t0, dur, pico, dest) {
    const o = ctx.createOscillator(), g = ganho();
    o.type = tipo; o.frequency.setValueAtTime(f0, t0); o.frequency.exponentialRampToValueAtTime(f1, t0 + dur);
    env(g, t0, 0.005, pico, dur);
    o.connect(g); g.connect(dest || bus.efeitos); o.start(t0); o.stop(t0 + dur + 0.05);
  }
  function estalo(t0, dur, tipo, freq, pico, dest) {
    const s = fonteRuido(t0, dur), f = filtro(tipo, freq, 0.8), g = ganho();
    env(g, t0, 0.003, pico, dur);
    s.connect(f); f.connect(g); g.connect(dest || bus.efeitos);
  }

  // ---- torcida de fundo: dois ruídos em loop (corpo grave + "falatório" médio)
  function montarTorcida() {
    torcidaGain = ganho(); torcidaGain.gain.value = 0.0001;
    torcidaFiltro = filtro('bandpass', 700, 0.5);
    const lp = filtro('lowpass', 2400, 0.5);
    const a = fonteRuido(ctx.currentTime, 0, true), b = fonteRuido(ctx.currentTime, 0, true);
    const corpo = filtro('bandpass', 300, 0.6), gCorpo = ganho(); gCorpo.gain.value = 0.6;
    // "Murmúrio": o volume do falatório sobe e desce devagar (oscilador lento no ganho).
    const gFala = ganho(); gFala.gain.value = 0.7;
    const lfo = ctx.createOscillator(), lfoG = ganho(); lfo.frequency.value = 0.23; lfoG.gain.value = 0.25;
    lfo.connect(lfoG); lfoG.connect(gFala.gain); lfo.start();
    a.connect(torcidaFiltro); torcidaFiltro.connect(gFala); gFala.connect(lp);
    b.connect(corpo); corpo.connect(gCorpo); gCorpo.connect(lp);
    lp.connect(torcidaGain); torcidaGain.connect(bus.torcida);
  }
  // ---- (7.4.9) A VOZ DA TORCIDA ----------------------------------------------------------------------------------------
  // PALMAS: 3 s de "claps" (rajadas curtinhas de ruído, ~170 por segundo, cada uma de um tamanho) gravados UMA vez num
  //   buffer; tocar é só ligar esse buffer num filtro e num envelope (barato, mesmo com muita gente batendo palma).
  let palmasBuf = null;
  function montarPalmas() {
    const sr = ctx.sampleRate, n = Math.floor(sr * 3);
    palmasBuf = ctx.createBuffer(1, n, sr);
    const d = palmasBuf.getChannelData(0);
    for (let c = 0; c < 510; c++) {
      const i0 = Math.floor(Math.random() * n), len = Math.floor(sr * rand(0.008, 0.022)), a = rand(0.25, 1);
      for (let j = 0; j < len; j++) { const i = (i0 + j) % n; d[i] += (Math.random() * 2 - 1) * a * Math.exp(-j / (len * 0.35)); }
    }
    let mx = 0; for (let i = 0; i < n; i++) mx = Math.max(mx, Math.abs(d[i]));
    for (let i = 0; i < n; i++) d[i] *= 0.9 / (mx || 1);
  }
  // CORO: poucas vozes (dente de serra, cada uma um pouco desafinada e atrasada) passando por dois filtros de FORMANTE,
  //   que fazem a vogal (ô, é, á, u). notas = [[semitom, duração, vogal], ...] (semitom null = pausa). Cada sílaba tem
  //   ataque e uma caidinha no fim, para notas repetidas soarem separadas. op: base (Hz), vozes, ganho, desafina (cents),
  //   deslize (s: a voz escorrega de uma nota para outra), ataque (s), longe (0..1: mais abafado, a torcida do outro lado).
  const VOGAIS = { o: [480, 880], e: [430, 1850], a: [720, 1180], u: [320, 720], i: [300, 2250] };
  function coro(t0, notas, op) {
    const nV = op.vozes || 6, f1 = filtro('bandpass', 500, 2.5), f2 = filtro('bandpass', 1000, 3.5), g2 = ganho();
    const lp = filtro('lowpass', 3400 - 2200 * (op.longe || 0), 0.6), saida = ganho();
    g2.gain.value = 0.5; saida.gain.value = op.ganho;
    f1.connect(lp); f2.connect(g2); g2.connect(lp); lp.connect(saida); saida.connect(op.dest || bus.torcida);
    let t = t0;
    for (const [, dur, vog] of notas) { const V = VOGAIS[vog || 'o']; f1.frequency.setTargetAtTime(V[0], t, 0.03); f2.frequency.setTargetAtTime(V[1], t, 0.03); t += dur; }
    const fim = t, at = op.ataque || 0.02, primeira = notas.find((n) => n[0] != null);
    for (let v = 0; v < nV; v++) {
      const o = ctx.createOscillator(), g = ganho(), atraso = rand(0, 0.07), base = op.base * (v === nV - 1 && nV > 4 ? 2 : 1) * Math.pow(2, rand(-1, 1) * (op.desafina || 25) / 1200);
      o.type = 'sawtooth';
      o.frequency.setValueAtTime(base * Math.pow(2, (primeira ? primeira[0] : 0) / 12), t0);
      g.gain.setValueAtTime(0, t0);
      let tt = t0 + atraso;
      for (const [semi, dur] of notas) {
        if (semi == null) { g.gain.setTargetAtTime(0, tt, 0.04); tt += dur; continue; }
        o.frequency.setTargetAtTime(base * Math.pow(2, semi / 12), tt, op.deslize || 0.02);
        g.gain.setTargetAtTime(1, tt, at);
        g.gain.setTargetAtTime(0.3, tt + dur * 0.8, 0.03);
        tt += dur;
      }
      g.gain.setTargetAtTime(0, tt, op.solta || 0.08);
      o.connect(g); g.connect(f1); g.connect(f2);
      o.start(t0); o.stop(fim + 0.8);
    }
    return fim - t0;
  }
  // "Ar" da multidão junto do coro (ruído filtrado com envelope).
  function arDaTorcida(t0, dur, pico, freq, ataque) {
    const s = fonteRuido(t0, dur + 0.6), bp = filtro('bandpass', freq || 700, 0.8), g = ganho();
    g.gain.setValueAtTime(0.0001, t0); g.gain.linearRampToValueAtTime(pico, t0 + (ataque || 0.3));
    g.gain.setValueAtTime(pico, t0 + Math.max(ataque || 0.3, dur - 0.3)); g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur + 0.5);
    s.connect(bp); bp.connect(g); g.connect(bus.torcida);
  }
  // (7.4.11) A BATERIA COM AMOSTRAS: o bumbo e a caixa são sintetizados UMA vez em buffers (montarBateria); cada batida é só
  //   um BufferSource + um ganho. Antes cada batida criava osciladores, ruído e filtros — com o gol, as palmas e a torcida
  //   juntos eram centenas de nós de áudio ao mesmo tempo, o som chiava e às vezes parava de sair.
  let bumboBuf = null, caixaBuf = null;
  function montarBateria() {
    const sr = ctx.sampleRate;
    const nb = Math.floor(sr * 0.32); bumboBuf = ctx.createBuffer(1, nb, sr);
    const b = bumboBuf.getChannelData(0); let fase = 0;
    for (let i = 0; i < nb; i++) { const t = i / sr, f = 46 + 50 * Math.exp(-t / 0.05); fase += 2 * Math.PI * f / sr; b[i] = Math.sin(fase) * Math.exp(-t / 0.1) * 0.95 + (i < sr * 0.004 ? (Math.random() * 2 - 1) * 0.3 * (1 - i / (sr * 0.004)) : 0); }
    const nc = Math.floor(sr * 0.16); caixaBuf = ctx.createBuffer(1, nc, sr);
    const c = caixaBuf.getChannelData(0); let ant = 0;
    for (let i = 0; i < nc; i++) { const t = i / sr, x = (Math.random() * 2 - 1) * Math.exp(-t / 0.035) * 0.8 + Math.sin(2 * Math.PI * 195 * t) * Math.exp(-t / 0.03) * 0.35; c[i] = x - ant * 0.55; ant = x; }
  }
  function batida(buf, t, v, dest, taxa) {
    if (!buf) return;
    const s2 = ctx.createBufferSource(), g = ganho(); s2.buffer = buf; if (taxa) s2.playbackRate.value = taxa;
    g.gain.value = clamp(v, 0, 1.2); s2.connect(g); g.connect(dest); s2.start(t);
  }
  function barramento(longe) { const g = ganho(), lp = filtro('lowpass', 6000 - 4000 * (longe || 0), 0.6); g.connect(lp); lp.connect(bus.torcida); return g; }
  // bateria da organizada: bumbo nos tempos e caixa nos contratempos (k = volume, longe = abafado)
  function bateria(t0, dur, k, bpm, longe) {
    const b = 60 / (bpm || 124), bus = barramento(longe); bus.gain.value = 1 - 0.5 * (longe || 0);
    for (let i = 0; i * b / 2 < dur; i++) {
      const t = t0 + i * b / 2;
      if (i % 2 === 0) batida(bumboBuf, t, (i % 4 === 0 ? 0.5 : 0.36) * k, bus);
      else batida(caixaBuf, t, (i % 4 === 3 ? 0.2 : 0.12) * k, bus);
    }
  }
  // batucada de samba (a festa): surdo marcando, caixa e o tamborim agudo (a caixa tocada mais rápido)
  function batucada(t0, dur, k) {
    const passo = 60 / 104 / 4, bus = barramento(0);
    const SURDO = 'X.......x.......', CAIXA = 'x.xx.xx.x.xx.xx.', TAMB = 'x.xx.x.xx.xx.x.x';
    for (let i = 0; i * passo < dur; i++) {
      const s2 = i % 16, t = t0 + i * passo, fade = Math.min(1, (dur - i * passo) / 1.2);
      if (SURDO[s2] !== '.') batida(bumboBuf, t, (SURDO[s2] === 'X' ? 0.55 : 0.4) * k * fade, bus, 0.78);
      if (CAIXA[s2] !== '.') batida(caixaBuf, t, 0.16 * k * fade, bus);
      if (TAMB[s2] !== '.') batida(caixaBuf, t, 0.1 * k * fade, bus, 2.2);
    }
  }
  // (7.4.11) os sons "pesados" (coro de vozes, bateria, batuque) têm um limite próprio: no máximo 3 ao mesmo tempo
  let pesados = 0;
  function pesado(dur) {
    if (pesados >= 3) return false;
    pesados++; setTimeout(() => { pesados = Math.max(0, pesados - 1); }, dur * 1000 + 100);
    return true;
  }
  function tocarPalmas(t0, dur, k) {
    if (!palmasBuf) return;
    const s = ctx.createBufferSource(); s.buffer = palmasBuf; s.loop = true;
    const bp = filtro('bandpass', 1500, 0.7), g = ganho();
    g.gain.setValueAtTime(0.0001, t0); g.gain.linearRampToValueAtTime(0.55 * k, t0 + 0.25);
    g.gain.setValueAtTime(0.55 * k, t0 + dur * 0.45); g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    s.connect(bp); bp.connect(g); g.connect(bus.torcida);
    s.start(t0, Math.random() * 2.5); s.stop(t0 + dur + 0.05);
  }
  // nivel 0..1 (chamado todo quadro; só mexe no som quando muda de verdade)
  function torcida(nivel) {
    if (!ctx || !torcidaGain) return;
    if (nivel < 0) { if (nivelAtual !== -2) { nivelAtual = -2; torcidaGain.gain.setTargetAtTime(0, ctx.currentTime, 0.25); } return; }   // silêncio total (menu, criador, fases)
    const n = Math.round(clamp(nivel, 0, 1) * 20) / 20;
    if (n === nivelAtual) return;
    nivelAtual = n;
    const t = ctx.currentTime;
    torcidaGain.gain.setTargetAtTime(0.05 + 0.2 * n, t, 0.6);
    torcidaFiltro.frequency.setTargetAtTime(600 + 700 * n, t, 0.6);
  }

  return {
    ligar, torcida,
    // (7.4.0) os fogos da cena do estádio: 'sobe' (o assovio do rojão subindo) e 'estouro' (o estrondo e o chiado das faíscas);
    // longe = 0..1 (o estádio visto de fora fica mais abafado)
    fogo(tipo, longe) {
      if (!pronto() || !vaga(tipo === 'sobe' ? 1.2 : 1.6)) return;
      const t = ctx.currentTime, k = 1 - 0.55 * clamp(longe || 0, 0, 1);
      if (tipo === 'sobe') { tom('sine', 900 + Math.random() * 300, 2400 + Math.random() * 600, t, 0.9, 0.035 * k); estalo(t, 0.9, 'highpass', 3000, 0.02 * k); return; }
      tom('sine', 95, 38, t, 0.7, 0.5 * k); estalo(t, 0.35, 'lowpass', 900, 0.55 * k);
      for (let i = 0; i < 7; i++) estalo(t + 0.18 + Math.random() * 0.9, 0.05, 'highpass', 2500 + Math.random() * 2500, (0.08 + Math.random() * 0.08) * k);   // o chiado
    },
    get mudo() { return mudo; },
    // para o Mumble (fala) e as fases usarem o mesmo áudio. (7.4.13) "mestre" agora é o barramento dos EFEITOS (o que as fases
    //   tocam por ele obedece ao volume de efeitos); música e vozes têm o seu (musica, vozes); "geral" é o volume de tudo.
    get audio() { return ctx ? { ctx, mestre: bus.efeitos || mestre, geral: mestre, efeitos: bus.efeitos, torcida: bus.torcida, musica: bus.musica || mestre, vozes: bus.vozes || mestre } : null; },
    CATEGORIAS: CATS,
    volume(cat) { return VOL[cat] ?? 1; },
    mudoDe(cat) { return !!MUDO[cat]; },
    ajustarVolume(cat, v, mudar) {
      if (!(cat in VOL)) return;
      if (v != null) VOL[cat] = clamp(Number(v) || 0, 0, 1);
      if (mudar != null) MUDO[cat] = !!mudar;
      if (cat === 'geral' && mudar === false && mudo) { mudo = false; try { localStorage.setItem('futebolJsMudo', '0'); } catch (e) { /* ok */ } }
      aplicarVolumes(); guardarVolumes();
    },

    alternarMudo() {
      mudo = !mudo;
      try { localStorage.setItem('futebolJsMudo', mudo ? '1' : '0'); } catch (e) { /* ok */ }
      aplicarVolumes();
      return mudo;
    },
    pausar(p) { if (ctx) { if (p) ctx.suspend(); else ctx.resume(); } },
    // forca 0..1
    chute(forca) {
      if (!pronto() || !vaga(0.25)) return;
      const t = ctx.currentTime, f = clamp(forca, 0, 1);
      tom('sine', 140 + 60 * f, 45, t, 0.18, 0.55 + 0.4 * f);
      estalo(t, 0.06, 'bandpass', 1800, 0.25 + 0.35 * f);
    },
    // cada toque sai um pouco diferente — altura, duração, "estalo" e às vezes um
    // segundo toquinho (a bola quicando no pé). Assim passes seguidos não soam repetidos.
    toque(forca = 0.3) {
      if (!pronto() || !vaga(0.15)) return;
      const t = ctx.currentTime, f = clamp(forca, 0, 1);
      const f0 = rand(190, 300), dur = rand(0.055, 0.1);
      tom(Math.random() < 0.7 ? 'sine' : 'triangle', f0, f0 * rand(0.4, 0.55), t, dur, (0.18 + 0.25 * f) * rand(0.8, 1.15));
      estalo(t, rand(0.015, 0.035), Math.random() < 0.5 ? 'highpass' : 'bandpass', rand(1800, 3600), (0.05 + 0.1 * f) * rand(0.7, 1.3));
      if (Math.random() < 0.3) tom('sine', f0 * 0.8, f0 * 0.4, t + rand(0.03, 0.06), 0.05, 0.08 + 0.08 * f);   // quique no pé
    },
    // Trave/travessão: "plém" metálico — tons que NÃO são harmônicos entre si (é o que soa a metal),
    // cada um sumindo num tempo diferente, mais um estalo na batida.
    trave(vel = 15) {
      if (!pronto() || !vaga(1.6)) return;
      const t = ctx.currentTime, k = clamp(vel / 25, 0.3, 1);
      const base = rand(480, 560);
      [[1, 1.5, 0.3], [2.76, 1.1, 0.18], [5.4, 0.7, 0.1], [8.93, 0.45, 0.06]].forEach(([m, dur, pico]) => {
        tom('sine', base * m, base * m * 0.995, t, dur, pico * k);
      });
      estalo(t, 0.03, 'highpass', 3000, 0.3 * k);
    },
    // Chute para fora: "óóóh..." da torcida, caindo no fim (decepção).
    ohh() {
      if (!pronto() || !vaga(2)) return;
      const t = ctx.currentTime;
      const vog = filtro('bandpass', 520, 1.6), g = ganho();
      g.gain.setValueAtTime(0.0001, t);
      g.gain.linearRampToValueAtTime(0.12, t + 0.25);
      g.gain.setValueAtTime(0.12, t + 0.7);
      g.gain.exponentialRampToValueAtTime(0.0001, t + 1.8);
      vog.connect(g); g.connect(bus.torcida);
      for (let i = 0; i < 8; i++) {
        const o = ctx.createOscillator(), f0 = rand(190, 300);
        o.type = 'sawtooth';
        o.frequency.setValueAtTime(f0, t); o.frequency.setValueAtTime(f0, t + 0.6);
        o.frequency.exponentialRampToValueAtTime(f0 * 0.78, t + 1.7);    // a voz "cai" no fim
        o.connect(vog); o.start(t + rand(0, 0.08)); o.stop(t + 1.85);
      }
      const s = fonteRuido(t, 1.8), bp = filtro('bandpass', 480, 1.2), gn = ganho();   // "ar" da multidão
      gn.gain.setValueAtTime(0.0001, t); gn.gain.linearRampToValueAtTime(0.14, t + 0.25);
      gn.gain.exponentialRampToValueAtTime(0.0001, t + 1.8);
      s.connect(bp); bp.connect(gn); gn.connect(bus.torcida);
    },
    // Passo na grama: "chhk" bem baixinho (ruído médio-agudo curtinho) + um toque grave quase mudo.
    passo() {
      if (!pronto() || !vaga(0.1)) return;
      const t = ctx.currentTime;
      estalo(t, rand(0.04, 0.07), 'bandpass', rand(1500, 2600), rand(0.035, 0.055));
      tom('sine', rand(80, 100), 50, t, 0.05, 0.03);
    },
    apito(dur = 0.3, atraso = 0) {
      if (!pronto() || !vaga(dur + atraso)) return;
      const t = ctx.currentTime + atraso;
      const o = ctx.createOscillator(), o2 = ctx.createOscillator(), g = ganho(), bp = filtro('bandpass', 2900, 3);
      o.type = 'sine'; o.frequency.value = 2850; o2.type = 'triangle'; o2.frequency.value = 2860;
      const lfo = ctx.createOscillator(), lfoG = ganho(); lfo.type = 'square'; lfo.frequency.value = 32; lfoG.gain.value = 130;
      lfo.connect(lfoG); lfoG.connect(o.frequency); lfoG.connect(o2.frequency);
      g.gain.setValueAtTime(0.0001, t);
      g.gain.exponentialRampToValueAtTime(0.32, t + 0.02);
      g.gain.setValueAtTime(0.32, t + dur - 0.05);
      g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      o.connect(bp); o2.connect(bp); bp.connect(g); g.connect(bus.efeitos);
      for (const x of [o, o2, lfo]) { x.start(t); x.stop(t + dur + 0.05); }
    },
    apitoFinal() { this.apito(0.32, 0); this.apito(0.32, 0.5); this.apito(1.15, 1.0); },
    // Gol: a torcida SOBE em ~1 s e fica alta e constante até a saída de bola (Som.fimGol(),
    // chamado no kickoff), aí baixa devagar em ~2,5 s. Segurança: no máximo 45 s.
    // (7.4.9) k = o tamanho da torcida de quem fez (0..1; sem k = 1). Torcida grande: o grito "GOOOL" (coro subindo),
    //   o estouro no começo e a bateria da organizada por cima; gol do visitante com pouca gente: só a festa pequena dele.
    gol(k = 1) {
      if (!pronto()) return;
      this.fimGol();
      const t = ctx.currentTime, MAX = 45, kk = clamp(k, 0.15, 1.2);
      const s = fonteRuido(t, MAX), bp = filtro('bandpass', 900, 0.5), lp = filtro('lowpass', 3000, 0.5), g = ganho();
      g.gain.setValueAtTime(0.0001, t); g.gain.linearRampToValueAtTime(0.3 * kk, t + 1.1);
      s.connect(bp); bp.connect(lp); lp.connect(g); g.connect(bus.torcida);
      if (kk > 0.45 && pesado(8)) {
        arDaTorcida(t, 1.2, 0.32 * kk, 1400, 0.08);                                  // o estouro
        coro(t + 0.05, [[0, 0.9, 'a'], [5, 2.6, 'e'], [7, 0.9, 'e']], { base: 205, vozes: 8, ganho: 0.08 * kk, desafina: 45, deslize: 0.3, ataque: 0.1, solta: 0.5 });   // (7.4.10) "AAAAA-ÊÊÊÊÊ!" (o "GOOOL" com o ô fechado soava triste)
        bateria(t + 2.2, 7, 0.9 * kk, 132);
      }
      const vog = filtro('bandpass', 700, 0.9), gv = ganho();
      gv.gain.setValueAtTime(0.0001, t); gv.gain.linearRampToValueAtTime(0.07 * kk, t + 1.0);
      vog.connect(gv); gv.connect(bus.torcida);
      const fontes = [s];
      for (let i = 0; i < 9; i++) {
        const o = ctx.createOscillator(), f0 = rand(180, 330);
        o.type = 'sawtooth'; o.frequency.value = f0;
        const vib = ctx.createOscillator(), vg = ganho(); vib.frequency.value = rand(0.3, 1.2); vg.gain.value = f0 * 0.03;   // ondulação lenta
        vib.connect(vg); vg.connect(o.frequency);
        o.connect(vog); o.start(t + rand(0, 0.4)); o.stop(t + MAX); vib.start(t); vib.stop(t + MAX);
        fontes.push(o, vib);
      }
      golAtivo = { ganhos: [[g, 0.3 * kk], [gv, 0.07 * kk]], fontes, t0: t };
    },
    fimGol() {
      if (!ctx || !golAtivo) return;
      const t = ctx.currentTime, G2 = golAtivo; golAtivo = null;
      // (7.4.9) o nível de onde baixa é o que foi programado (g.gain.value pode não refletir a rampa e dar um estalo)
      for (const [g, alvo] of G2.ganhos) { const nv = Math.max(0.0001, alvo * clamp((t - G2.t0) / 1.1, 0, 1)); g.gain.cancelScheduledValues(t); g.gain.setValueAtTime(nv, t); g.gain.linearRampToValueAtTime(0.0001, t + 2.5); }
      for (const f of G2.fontes) { try { f.stop(t + 2.6); } catch (e) { /* já parou */ } }
    },
    // (7.4.9) CANTO da torcida: um dos CANTOS (qual: -1 = sorteado), duas vezes, com a bateria. k = 0..1 (quanta gente),
    //   longe = 0..1 (a torcida do outro lado soa mais abafada). Devolve quanto tempo dura (0 se não tocou).
    // (7.4.11) BATUQUE (a festa da torcida: surdo, caixa e tamborim), dur segundos, depois de "atraso" segundos
    batuque(k = 0.6, dur = 5, atraso = 0) {
      if (!pronto() || k < 0.05 || !pesado(dur + atraso)) return;
      batucada(ctx.currentTime + atraso, dur, clamp(k, 0, 1));
    },
    // VAIA: "uuuuu" grave e desafinado (muita gente), subindo devagar, com ASSOBIOS agudos espalhados.
    vaia(k = 0.6, dur = 2.5) {
      if (!pronto() || k < 0.05 || !pesado(dur + 1) || !vaga(dur + 1)) return;
      const t = ctx.currentTime, kk = clamp(k, 0, 1);
      coro(t, [[0, dur * 0.6, 'u'], [-2, dur * 0.4, 'u']], { base: 132, vozes: 8, ganho: 0.075 * kk, desafina: 90, deslize: 0.5, ataque: 0.35, solta: 0.45 });
      arDaTorcida(t, dur, 0.06 * kk, 380, 0.4);
      for (let i = 0, n = Math.round(3 + 6 * kk); i < n; i++) {                        // assobios ("fiiiu")
        const t0 = t + rand(0, dur * 0.85), d = rand(0.35, 1.0), f = rand(2300, 3500), o = ctx.createOscillator(), g = ganho(), lfo = ctx.createOscillator(), lg = ganho();
        o.type = 'sine'; o.frequency.setValueAtTime(f, t0); o.frequency.linearRampToValueAtTime(f * rand(0.92, 1.05), t0 + d);
        lfo.frequency.value = rand(5, 9); lg.gain.value = rand(20, 70); lfo.connect(lg); lg.connect(o.frequency);
        env(g, t0, 0.05, rand(0.015, 0.035) * kk, d);
        o.connect(g); g.connect(bus.torcida); o.start(t0); o.stop(t0 + d + 0.05); lfo.start(t0); lfo.stop(t0 + d + 0.05);
      }
    },
    // OLÉ! (drible): "o" curto e o "LÉ" lá em cima, todo mundo junto.
    ole(k = 0.6) {
      if (!pronto() || k < 0.05 || !pesado(1.0) || !vaga(1.2)) return;
      const t = ctx.currentTime, kk = clamp(k, 0, 1);
      coro(t, [[0, 0.17, 'o'], [5, 0.6, 'e']], { base: 228, vozes: 8, ganho: 0.14 * kk, desafina: 35, ataque: 0.015, solta: 0.18 });
      arDaTorcida(t + 0.12, 0.5, 0.07 * kk, 1100, 0.05);
    },
    // UUUUH (bola na trave): sobe e cai devagar, "u" fechado — todo o estádio.
    uuh(k = 0.8) {
      if (!pronto() || !pesado(2.2) || !vaga(2.4)) return;
      const t = ctx.currentTime, kk = clamp(k, 0.2, 1);
      coro(t, [[0, 0.35, 'u'], [4, 0.75, 'u'], [-3, 0.9, 'o']], { base: 188, vozes: 9, ganho: 0.1 * kk, desafina: 45, deslize: 0.22, ataque: 0.1, solta: 0.4 });
      arDaTorcida(t, 1.7, 0.12 * kk, 420, 0.2);
    },
    // PALMAS (depois de um ataque, de uma defesa, no fim do jogo). atraso em segundos.
    palmas(k = 0.5, dur = 2.4, atraso = 0) {
      if (!pronto() || !vaga(dur + atraso) || k < 0.05) return;
      tocarPalmas(ctx.currentTime + atraso, dur, clamp(k, 0, 1));
    },
    // VIBRA (defesa do goleiro): "êêêh!" curto da torcida dele + palmas.
    vibra(k = 0.6) {
      if (!pronto() || k < 0.05 || !pesado(2.2) || !vaga(2.5)) return;
      const t = ctx.currentTime + 0.25, kk = clamp(k, 0, 1);
      coro(t, [[0, 0.3, 'e'], [3, 1.1, 'e']], { base: 236, vozes: 8, ganho: 0.085 * kk, desafina: 40, deslize: 0.15, ataque: 0.06, solta: 0.35 });
      arDaTorcida(t, 1.3, 0.1 * kk, 900, 0.1);
      tocarPalmas(t + 0.6, 2.2, kk * 0.8);
    },
    defesa() {
      if (!pronto() || !vaga(1.3)) return;
      const t = ctx.currentTime;
      estalo(t, 0.12, 'lowpass', 600, 0.7);                 // "pof" das luvas
      tom('sine', 110, 60, t, 0.12, 0.45);
      const s = fonteRuido(t, 1.3), bp = filtro('bandpass', 450, 1.4), g = ganho();   // "uuuh"
      env(g, t + 0.05, 0.2, 0.22, 1.3);
      s.connect(bp); bp.connect(g); g.connect(bus.torcida);
    },
    // (7.4.13) FLASH de câmera de foto (a premiação): o obturador abrindo e fechando ("tchc-tic") e o "piiu" agudo do flash
    //   carregando. longe = 0..1 (fotógrafo mais longe: mais baixo)
    flash(longe = 0) {
      if (!pronto() || !vaga(0.32)) return;
      const t = ctx.currentTime, k = 1 - 0.5 * clamp(longe, 0, 1);
      estalo(t, 0.016, 'highpass', 3800, 0.3 * k);
      estalo(t + 0.042, 0.022, 'bandpass', 2300, 0.2 * k);
      tom('sine', 3000, 7600, t + 0.05, 0.24, 0.016 * k);
    },
    // tipo: 'ok' | 'erro' | 'perfeito'
    clique(tipo = 'ok') {
      if (!pronto() || !vaga(0.35)) return;
      const t = ctx.currentTime;
      if (tipo === 'perfeito') { [880, 1320, 1760].forEach((f, i) => tom('sine', f, f, t + i * 0.07, 0.12, 0.22)); return; }
      if (tipo === 'erro') { tom('square', 320, 200, t, 0.09, 0.09); return; }
      tom('square', 1400, 1350, t, 0.04, 0.1);
    },
    drible() {
      if (!pronto() || !vaga(0.4)) return;
      const t = ctx.currentTime, s = fonteRuido(t, 0.4), bp = filtro('bandpass', 500, 1.2), g = ganho();
      bp.frequency.setValueAtTime(450, t); bp.frequency.exponentialRampToValueAtTime(3000, t + 0.32);
      env(g, t, 0.06, 0.35, 0.38);
      s.connect(bp); bp.connect(g); g.connect(bus.efeitos);
    },
  };
})();
// O som só pode ligar depois de um toque/clique do jogador (regra dos navegadores).
window.addEventListener('pointerdown', () => Som.ligar(), { passive: true, capture: true });
window.addEventListener('touchend', () => Som.ligar(), { passive: true, capture: true });   // (7.4.11) o iPhone só deixa acordar o áudio num toque
window.addEventListener('keydown', () => Som.ligar());
document.addEventListener('visibilitychange', () => { if (!document.hidden) Som.ligar(); });

// Quão "quente" está o jogo para a torcida de fundo (0 a 1): bola perto de um gol, chute no ar.
// (7.4.9) Gol do visitante: a casa fica quieta (só a torcida dele, menor, faz barulho). Ataque do visitante: a casa
//   fica tensa (o barulho sobe menos); ataque da casa: sobe mais.
function nivelTorcida() {
  if (G.state === 'menu' || G.state === 'end') return 0;
  const casa = PARTIDA ? PARTIDA.mandante : 0, parte = (t) => crowd.parte(t);
  if (G.state === 'goal' || G.state === 'celebrate') return G.scoredBy >= 0 ? clamp(0.15 + 0.75 * parte(G.scoredBy), 0.2, 0.75) : 0.6;
  if (G.state === 'fim') return 0.6;
  if (Torcida.quieta()) return 0.1;
  const d = Math.min(Math.abs(HALF_L - ball.x), Math.abs(-HALF_L - ball.x)) + Math.abs(ball.z) * 0.3;
  let n = clamp(1 - (d - 8) / 40, 0, 1) * 0.8;
  if (ball.isShot) n = 1;
  const ataca = ball.x > 0 ? 0 : 1;                                  // o time 0 ataca o gol de x > 0
  return n * (ataca === casa ? 1 : 0.55 + 0.45 * parte(ataca));
}

// ---------------------------------------------------------------------
// (7.4.9) A TORCIDA REAGE AO JOGO (o som da Som + a arquibancada pulando no crowd).
//   Quem é "da casa" = PARTIDA.mandante. O tamanho de cada torcida vem dos torcedores DE VERDADE na arquibancada
//   (crowd.parte) e a lotação (crowd.lotacao) dá o volume: estádio cheio é bem mais alto que a várzea.
//   canto ...... de tempos em tempos a torcida canta para o time (a da casa bem mais), com bumbo e caixa, e pula no ritmo
//   vaia ....... o visitante fica com a bola: às vezes a casa vaia (com assobios); no pênalti do visitante, também
//   gol ........ a festa da torcida de quem fez, do tamanho dela; gol do visitante: a casa fica quieta uns 9 s
//   olé ........ drible que deu certo (a torcida de quem driblou) · uuuh: bola na trave (o estádio todo)
//   palmas ..... o ataque acabou num chute para fora ou defendido (a torcida de quem atacou aplaude mesmo assim)
//   defesa ..... a torcida do goleiro vibra ("êêê" e palmas)
// ---------------------------------------------------------------------
// (7.4.11) Sem os cânticos (pesavam no áudio e o som chiava/sumia): a torcida faz festa no gol (o grito e a bateria),
//   olé, uuuh, palmas, vaia e a vibração da defesa.
const Torcida = (() => {
  let vaiaCd = 10, posseT = 0, quietaT = 0, oleT = 0, defT = -9;
  const casa = () => (PARTIDA ? PARTIDA.mandante : 0);
  const ligada = () => !!PARTIDA && !PARTIDA.campo.semTorcida && !GANCHO_RENDER && G.state !== 'menu' && G.state !== 'end' && G.state !== 'paused' && !G.pulando && G.torcidaCena == null && crowd.total() > 20;   // treino / campo sem arquibancada: nada
  const kDe = (t) => crowd.lotacao() * Math.min(1, crowd.parte(t) * 1.4);   // 0..1: quanto barulho a torcida do time t faz
  function atualizar(dt) {
    if (!ligada()) return;
    quietaT = Math.max(0, quietaT - dt); oleT = Math.max(0, oleT - dt); vaiaCd -= dt;
    const h = G.possession;
    if (G.state === 'play' && h && h.team !== casa() && !G.pen && crowd.parte(casa()) > 0.5) {
      posseT += dt;
      if (posseT > 1.2 && vaiaCd <= 0 && Math.random() < dt * 0.35) { Som.vaia(kDe(casa()) * 0.9, rand(1.8, 3.2)); vaiaCd = rand(14, 30); }
    } else posseT = 0;
  }
  return {
    atualizar,
    quieta: () => quietaT > 0,
    // gol do time t (pen = gol na disputa de pênaltis: a festa é mais curta)
    gol(t, pen) {
      if (!PARTIDA || PARTIDA.campo.semTorcida) return;
      const k = kDe(t);
      Som.gol(Math.max(0.2, k * 1.1));
      if (pen) setTimeout(() => Som.fimGol(), 1600);
      if (t !== casa() && crowd.parte(casa()) > 0.5) quietaT = pen ? 3 : 9;      // a casa fica quieta
      else quietaT = 0;
      crowd.cantar(t, pen ? 2 : 7);                                                 // a torcida de quem fez pula junto com a bateria
    },
    ole(t, forte) {
      if (!ligada() || oleT > 0) return;
      oleT = 0.9;
      const k = kDe(t);
      Som.ole(k * (forte ? 1 : 0.8)); crowd.agitar(t, 0.55);
    },
    uuh(t) {
      if (!ligada()) return;
      Som.uuh(0.45 + 0.55 * crowd.lotacao()); crowd.agitar(0, 0.3); crowd.agitar(1, 0.3);
      if (t != null) Som.palmas(kDe(t) * 0.8, 2.2, 1.6);
    },
    // chute para fora: o "óóh" e as palmas de quem atacou
    fora(t) {
      if (!ligada()) return;
      Som.ohh();
      if (t != null) { Som.palmas(kDe(t) * 0.75, 2.2, 1.0); crowd.agitar(t, 0.25); }
    },
    defesa(gkTime) {
      if (!ligada() || gkTime == null || gkTime > 1 || G.time - defT < 2) return;
      defT = G.time;
      Som.vibra(kDe(gkTime)); crowd.agitar(gkTime, 0.6);
      Som.palmas(kDe(1 - gkTime) * 0.55, 2.0, 1.2);
    },
    // pênalti do visitante (na disputa e no jogo): a casa vaia e assobia antes da cobrança
    pressao(t) {
      if (!ligada() || t === casa() || crowd.parte(casa()) <= 0.5) return;
      Som.vaia(kDe(casa()), 2.8);
    },
    // cena do apito final / da disputa: a torcida de quem ganhou canta (e as duas aplaudem)
    festa(venc) {
      if (!PARTIDA || PARTIDA.campo.semTorcida || GANCHO_RENDER || crowd.total() <= 20) return;
      if (venc >= 0) { Som.palmas(kDe(venc), 3, 0.2); Som.batuque(kDe(venc), 5, 0.8); crowd.cantar(venc, 5); }   // palmas e o batuque de quem ganhou
      else Som.palmas(crowd.lotacao() * 0.7, 3, 0.3);
    },
    reiniciar() { vaiaCd = 10; posseT = 0; quietaT = 0; oleT = 0; defT = -9; },
    // antes da disputa de pênaltis: a torcida da casa canta
    prePenaltis() { if (ligada()) { Som.batuque(kDe(casa()) * 0.8, 6, 1.0); crowd.cantar(casa(), 6); } },   // o batuque da casa enquanto os times se preparam
  };
})();

function buildStands() {
  // Arquibancada em degraus nos quatro lados: degraus (concreto + cadeiras) num lote só e os
  // torcedores em outro (ver "TORCIDA" acima). Atrás do SEU gol (x < 0) é quase tudo azul,
  // atrás do gol deles quase tudo vermelho; nas laterais mistura, com blocos de cada time.
  const T = new Lote();
  const { FILEIRAS, ALT0, DEGRAU_Y, DEGRAU_Z, DIST0 } = ARQ;
  // POPULARIDADE: quanto mais popular o mandante (e um pouco o visitante), mais gente.
  // ocupacao = chance de cada cadeira ter alguém. casa = parte da torcida do mandante.
  const P = PARTIDA, popM = P ? P.timesObj[P.mandante].popularidade : 0.6, popV = P ? P.timesObj[1 - P.mandante].popularidade : 0.5;
  const ocupacao = clamp(0.18 + 0.62 * popM + 0.18 * popV, 0.12, 0.97);
  const casa = P ? P.mandante : 0;
  const partCasa = clamp(0.5 + 0.35 * (popM - popV) + 0.15, 0.35, 0.92);   // fração azul/vermelho nas laterais
  const timeTorcedor = (x) => {                     // laterais: mais torcida da casa no lado do gol dela
    const ladoCasa = casa === 0 ? -1 : 1;           // time 0 defende o gol de x < 0
    const p = clamp(partCasa + (x * ladoCasa / HALF_L) * 0.25, 0.05, 0.95);
    return Math.random() < p ? casa : 1 - casa;
  };
  const angulo = (x, z) => (Math.atan2(z, x) / (Math.PI * 2) + 1) % 1;
  for (let r = 0; r < FILEIRAS; r++) {
    const y = ALT0 + r * DEGRAU_Y, d = DIST0 + r * DEGRAU_Z;
    const concreto = r % 2 ? 0x3a414c : 0x343a44, cadeira = 0x26334a;
    for (const s of [-1, 1]) {
      const lenX = CONFIG.FIELD_L + 2 * (d + DEGRAU_Z), lenZ = CONFIG.FIELD_W + 2 * (d + DEGRAU_Z);
      T.caixa(lenX, y, DEGRAU_Z, concreto, 0, y / 2, s * (HALF_W + d + DEGRAU_Z / 2));
      T.caixa(lenX, 0.14, 0.45, cadeira, 0, y + 0.07, s * (HALF_W + d + 0.72));
      T.caixa(DEGRAU_Z, y, lenZ, concreto, s * (HALF_L + d + DEGRAU_Z / 2), y / 2, 0);
      T.caixa(0.45, 0.14, lenZ, cadeira, s * (HALF_L + d + 0.72), y + 0.07, 0);
      // Laterais (olhando para o centro do campo, em −s no Z).
      for (let x = -(HALF_L + d) + 0.5; x < HALF_L + d; x += 0.75) {
        if (Math.random() > ocupacao) continue;              // cadeira vazia
        const time = timeTorcedor(x), z = s * (HALF_W + d + 0.62);
        crowd.torcedor(x + rand(-0.12, 0.12), y + 0.14, z, 0, -s, time, Math.random() < 0.45, angulo(x, z));
      }
      // Fundos (atrás dos gols), olhando em −s no X: organizada, mais gente em pé.
      for (let z = -(HALF_W + d) + 0.5; z < HALF_W + d; z += 0.75) {
        if (Math.random() > Math.min(0.97, ocupacao * 1.08)) continue;   // atrás do gol: organizada, um pouco mais cheia
        const dono = s < 0 ? 0 : 1, time = Math.random() < 0.85 ? dono : 1 - dono, x = s * (HALF_L + d + 0.62);
        crowd.torcedor(x, y + 0.14, z + rand(-0.12, 0.12), -s, 0, time, Math.random() < 0.7, angulo(x, z));
      }
    }
  }
  const degraus = T.malha(MAT_CORES); ESTADIO.add(degraus); freeze(degraus);
  const torcida = crowd.malha(); ESTADIO.add(torcida); freeze(torcida);
  // Telhados e postes de luz num lote; lâmpadas (que brilham) em outro.
  const E = new Lote(), Lp = new Lote();
  for (const s of [-1, 1]) E.caixa(CONFIG.FIELD_L + 56, 0.6, 12, 0x2c3340, 0, 15, s * (HALF_W + 31));
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    E.caixa(0.8, 34, 0.8, 0x59606b, sx * (HALF_L + 33), 17, sz * (HALF_W + 33));
    Lp.caixa(4, 2, 0.8, 0xfff3c4, sx * (HALF_L + 33), 34, sz * (HALF_W + 33));
  }
  const estrutura = E.malha(MAT_CORES); ESTADIO.add(estrutura); freeze(estrutura);
  lampadasMat = new THREE.MeshBasicMaterial({ vertexColors: true });   // cor muda com o horário (aplicarAmbiente)
  const lampadas = Lp.malha(lampadasMat); ESTADIO.add(lampadas); freeze(lampadas);
}

// ESTÁDIO DA SÉRIE B (estadio 'arenaB'): o mesmo jeito do buildStands, só que mais simples e menor —
//   principal (atrás dos bancos, z < 0): 10 degraus de cimento com cobertura e colunas atrás · do outro lado: 7 degraus sem cobertura ·
//   atrás do gol da esquerda: a "geral" de 5 degraus, todo mundo em pé · atrás do gol da direita: muro pintado com o placar e árvores.
//   Sem cadeiras (o cimento é o assento), 4 refletores baixos. A ocupação vem do mandante (torcidaB de 0 a 1; sem ela, da popularidade).
function buildStandsB() {
  const T = new Lote();
  const DEG_Y = 0.55, DEG_Z = 0.95, D0 = 11.5;
  const P = PARTIDA, M = P ? P.timesObj[P.mandante] : null, V = P ? P.timesObj[1 - P.mandante] : null;
  const ocupacao = clamp(M && typeof M.torcidaB === 'number' ? M.torcidaB : 0.1 + 0.45 * (M ? M.popularidade : 0.5), 0.05, 0.92);
  const casa = P ? P.mandante : 0;
  const partCasa = clamp(0.78 + 0.15 * ((M ? M.popularidade : 0.5) - (V ? V.popularidade : 0.5)), 0.6, 0.95);   // visitante: pouca gente
  const angulo = (x, z) => (Math.atan2(z, x) / (Math.PI * 2) + 1) % 1;
  const ladoFora = casa === 0 ? 1 : -1;                                     // a torcida visitante fica num canto da arquibancada de frente
  const lances = [   // [eixo, sinal, fileiras, comprimento extra]
    { eixo: 'z', s: -1, n: 10 }, { eixo: 'z', s: 1, n: 7 }, { eixo: 'x', s: -1, n: 5, geral: true },
  ];
  for (const L of lances) {
    for (let r = 0; r < L.n; r++) {
      const y = 0.45 + r * DEG_Y, d = D0 + r * DEG_Z, cor = r % 2 ? 0x77736a : 0x6c6860;
      if (L.eixo === 'z') {
        const len = CONFIG.FIELD_L + 6;
        T.caixa(len, y, DEG_Z, cor, 0, y / 2, L.s * (HALF_W + d + DEG_Z / 2));
        for (let x = -len / 2 + 0.5; x < len / 2; x += 0.8) {
          if (Math.random() > ocupacao) continue;
          const z = L.s * (HALF_W + d + 0.55);
          const time = L.s > 0 && x * ladoFora > HALF_L * 0.55 ? 1 - casa : (Math.random() < partCasa ? casa : 1 - casa);
          crowd.torcedor(x + rand(-0.12, 0.12), y, z, 0, -L.s, time, Math.random() < 0.35, angulo(x, z));
        }
      } else {
        const len = CONFIG.FIELD_W * 0.7;
        T.caixa(DEG_Z, y, len, cor, L.s * (HALF_L + d + DEG_Z / 2), y / 2, 0);
        for (let z = -len / 2 + 0.5; z < len / 2; z += 0.7) {
          if (Math.random() > Math.min(0.95, ocupacao * 1.15)) continue;
          const x = L.s * (HALF_L + d + 0.55);
          crowd.torcedor(x, y, z + rand(-0.12, 0.12), -L.s, 0, Math.random() < 0.9 ? casa : 1 - casa, true, angulo(x, z));
        }
      }
    }
    // a parede de trás de cada lance (fecha o degrau mais alto) e as escadinhas pintadas de amarelo
    const n = L.n, yTopo = 0.45 + (n - 1) * DEG_Y, dTras = D0 + n * DEG_Z;
    if (L.eixo === 'z') {
      T.caixa(CONFIG.FIELD_L + 6, yTopo + 1.1, 0.3, 0x5c5850, 0, (yTopo + 1.1) / 2, L.s * (HALF_W + dTras + 0.15));
      for (const ex of [-CONFIG.FIELD_L / 4, 0, CONFIG.FIELD_L / 4]) for (let r = 0; r < n; r++) T.caixa(0.7, 0.02, DEG_Z * 0.9, 0xd8b030, ex, 0.45 + r * DEG_Y + 0.01, L.s * (HALF_W + D0 + r * DEG_Z + DEG_Z / 2));
    } else T.caixa(0.3, yTopo + 1.1, CONFIG.FIELD_W * 0.7, 0x5c5850, L.s * (HALF_L + dTras + 0.15), (yTopo + 1.1) / 2, 0);
  }
  // o muro atrás do gol da direita, com o placar velho em cima de duas pernas de ferro
  const xm = HALF_L + D0 + 1.5;
  T.caixa(0.4, 3.2, CONFIG.FIELD_W + 14, 0xd8d2c0, xm, 1.6, 0);
  T.caixa(0.42, 0.5, CONFIG.FIELD_W + 14, 0x2f7a3a, xm, 0.25, 0);
  for (const z of [-3.2, 3.2]) T.caixa(0.3, 6, 0.3, 0x55595f, xm + 0.6, 3, z);
  T.caixa(0.5, 2.6, 8, 0x1c1c1f, xm + 0.6, 7.2, 0);
  T.caixa(0.06, 2.2, 7.4, 0x2a2e36, xm + 0.33, 7.2, 0);
  const degraus = T.malha(MAT_CORES); ESTADIO.add(degraus); freeze(degraus);
  const torcida = crowd.malha(); ESTADIO.add(torcida); freeze(torcida);
  // cobertura da principal (laje fina inclinada, colunas atrás da última fileira) e os 4 refletores baixos
  const E = new Lote(), Lp = new Lote();
  const nP = 10, yP = 0.45 + (nP - 1) * DEG_Y, dP = D0 + nP * DEG_Z, prof = nP * DEG_Z + 2.4, zc = -(HALF_W + D0 + prof / 2 - 1.2);
  E.caixa(CONFIG.FIELD_L * 0.62, 0.35, prof, 0x9aa0a6, 0, yP + 4.2, zc);
  E.caixa(CONFIG.FIELD_L * 0.62, 0.6, 0.2, 0x3a64b8, 0, yP + 4.0, zc + prof / 2);
  for (let i = 0; i < 6; i++) E.caixa(0.35, yP + 4.2, 0.35, 0x55595f, lerp(-CONFIG.FIELD_L * 0.29, CONFIG.FIELD_L * 0.29, i / 5), (yP + 4.2) / 2, -(HALF_W + dP + 0.55));
  const H = 22;
  for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
    const x = sx * (HALF_L + 8), z = sz * (HALF_W + D0 + (sz < 0 ? nP : 7) * DEG_Z + 2.2);
    E.caixa(0.6, H, 0.6, 0x59606b, x, H / 2, z);
    E.caixa(3.2, 0.25, 0.9, 0x3a3f46, x, H + 0.2, z);
    Lp.caixa(3, 1.5, 0.7, 0xfff3c4, x, H + 1, z);
  }
  const estrutura = E.malha(MAT_CORES); ESTADIO.add(estrutura); freeze(estrutura);
  lampadasMat = new THREE.MeshBasicMaterial({ vertexColors: true });
  const lampadas = Lp.malha(lampadasMat); ESTADIO.add(lampadas); freeze(lampadas);
  // árvores atrás do muro (blocos)
  const A = new Lote();
  for (let i = 0; i < 9; i++) {
    const z = -CONFIG.FIELD_W / 2 - 4 + i * (CONFIG.FIELD_W + 8) / 8, x = xm + 4 + (i % 3) * 1.6, h = 3 + (i % 4) * 0.7;
    A.caixa(0.5, h, 0.5, 0x6b4a2a, x, h / 2, z); A.caixa(3, 2.6, 3, i % 2 ? 0x3f7a35 : 0x4a8a3c, x, h + 1.1, z);
  }
  const arv = A.malha(MAT_CORES); ESTADIO.add(arv); freeze(arv);
}

function buildGoal(side) {
  // Armação (traves, travessão e suporte das bolas reservas): 1 chamada de desenho.
  const pr = 0.12, gx = side * HALF_L;
  const A = new Lote();
  for (const z of [-GOAL_HALF, GOAL_HALF]) A.caixa(pr * 2, CONFIG.GOAL_H, pr * 2, 0xffffff, gx, CONFIG.GOAL_H / 2, z);
  A.caixa(pr * 2, pr * 2, CONFIG.GOAL_W + pr * 2, 0xffffff, gx, CONFIG.GOAL_H, 0);
  A.caixa(0.6, 0.5, 0.6, 0x2c3340, gx + side * 1.6, 0.25, GOAL_HALF + 2.5);
  const arm = A.malha(MAT_CORES); ESTADIO.add(arm); freeze(arm);
  // Rede (fundo, teto e laterais): 1 chamada de desenho.
  const net = new THREE.MeshBasicMaterial({
    map: drawTexture(32, 32, (g) => {
      g.fillStyle = 'rgba(255,255,255,0.75)';
      for (let i = 0; i < 32; i += 4) { g.fillRect(i, 0, 1, 32); g.fillRect(0, i, 32, 1); }
    }, 7, 3),
    transparent: true, side: THREE.DoubleSide, depthWrite: false,
  });
  const fx = gx + side * 2.2, H = CONFIG.GOAL_H, Z = GOAL_HALF;
  const R = new Lote();
  R.quad([fx, H, -Z], [fx, H, Z], [fx, 0, -Z], [fx, 0, Z], [-side, 0, 0]);                 // fundo
  R.quad([gx, H, -Z], [fx, H, -Z], [gx, H, Z], [fx, H, Z], [0, -1, 0]);                    // teto
  for (const z of [-Z, Z]) R.quad([gx, H, z], [fx, H, z], [gx, 0, z], [fx, 0, z], [0, 0, -Math.sign(z)]); // laterais
  const rede = R.malha(net); ESTADIO.add(rede); freeze(rede);
}

// (o estádio é montado em montarPartida → montarEstadio, no fim do arquivo)

// ---------------------------------------------------------------------
// 5. JOGADORES
// Boneco de blocos com as medidas do personagem do Super Lan Master.
// Estrutura: raiz (posição e giro) → corpo (balanço/inclinação) → pernas e braços em "pivôs".
// O boneco "olha" para +X; o lado direito dele é +Z local.
// ---------------------------------------------------------------------
const PELES = ['#F2C9A5', '#DDA67E', '#BF8159', '#946042', '#62402A'];
const CABELOS = ['#1C140F', '#3B2416', '#6B4423', '#C9A15A', '#0E0E0E'];

// PERSONALIZAÇÃO DO PERSONAGEM (modo história). Tudo é DADO: para criar um corte novo, basta uma
// linha em ESTILOS_CABELO / ESTILOS_BARBA / ROSTOS. Cada caixa é [largura(x), altura, profundidade(z), x, y, z, mix];
// o boneco olha para +X (frente) e a cabeça vai de x -0,24 a 0,24, de y 1,36 a 1,88 e de z -0,26 a 0,26.
// mix (opcional) = quanto a cor se mistura com a pele (0 = cor do cabelo, 1 = pele): faz o "degradê"/raspado.
// Os 3 primeiros cortes são os que os outros jogadores já usavam (índices antigos preservados).
const PELES_FITZ = [   // escala de Fitzpatrick (I a VI), na ordem da imagem de referência
  { id: 'I',   nome: 'Tipo I · muito clara',      cor: '#F3D5BC' },
  { id: 'II',  nome: 'Tipo II · clara',            cor: '#E3B592' },
  { id: 'III', nome: 'Tipo III · média',           cor: '#C99A77' },
  { id: 'IV',  nome: 'Tipo IV · morena',           cor: '#A8734C' },
  { id: 'V',   nome: 'Tipo V · parda escura',      cor: '#7C4A2A' },
  { id: 'VI',  nome: 'Tipo VI · negra',            cor: '#3E2723' },
];
const CORES_CABELO = [
  { nome: 'Preto', cor: '#15100D' }, { nome: 'Castanho escuro', cor: '#3B2416' }, { nome: 'Castanho', cor: '#6B4423' },
  { nome: 'Castanho claro', cor: '#8E6A3F' }, { nome: 'Loiro', cor: '#C9A15A' }, { nome: 'Ruivo', cor: '#A4482A' },
  { nome: 'Grisalho', cor: '#8D8F93' }, { nome: 'Branco', cor: '#D8D8D8' },
];
// Cada corte tem: caixas (volumes 3D, sempre ENCOSTANDO uns nos outros: topo + frente/atrás/laterais se sobrepõem) e a pintura
// na textura da cabeça (laterais e nuca): a = linha onde o cabelo começa, s = até onde ele é cheio, f = até onde vai o tom mais
// opaco (faixa lisa, sem quadradinhos), n/nf = o mesmo para a nuca, t = linhas de testa/franja, p = patilha (cabelo na lateral
// do rosto). Linhas vão de 0 (topo da cabeça) a 15 (queixo): cada linha tem ~3 cm. tipo 'degrade' = com pixels (fade), 'liso' = faixa.
// Opcionais (usados nos cortes da barbearia, cosmeticos.js): cor = o corte tem cor própria (platinado, colorido: ignora a cor de cabelo
// escolhida) · na caixa, a mistura pode ser uma cor ('#E8DFC4'): aquela caixa sai nessa cor (luzes, pontas) · desenho = 16 linhas de 16
// letras pintadas por cima das laterais ('#' = raspado na pele, '+' = cabelo, '.' = nada; a frente fica à direita e o outro lado sai
// espelhado) · desenhoNuca = o mesmo na nuca.
