    const gx = p.dir * HALF_L, zLado = Math.sign(p.z || 1) * Math.max(Math.abs(p.z), GOAL_HALF + 2.2);
    const alvo = { x: gx - p.dir * Math.max(SMALL_BOX.depth * 1.15, 3.2), z: clamp(zLado, -HALF_W + 1.4, HALF_W - 1.4) };
