  setLetterbox(false);
  G.tempo = 2; G.clock = duracaoTempo(); G.paradas = 0; G.acrescimo = 0; G.acrescimoDado = false; G.fimPendente = false;
  for (const p of players) if (!p.out) { p.folego = Math.min(1, (p.folego ?? 1) + 0.3); p.cansadoT = 0; }
