// =====================================================================
// PULAR CENA — vale para TODA cutscene (história, tutorial, abertura). Um botão "Pular cena ▶" aparece enquanto uma cena roda;
// tocando nele a cena vai direto para o ESTADO FINAL dela: as esperas (Cena.esperar) passam na hora, as falas fecham sozinhas, as
// telas pretas e contadores terminam, e as fases rodam a simulação em alta velocidade (Cena.passos(): andar, portas, câmera...) até o fim.
// Assim cada cena chega no fim do jeito certo (cada um no lugar onde termina), sem precisar escrever o "estado final" de cada uma.
// O pulo PARA sozinho quando o jogador tem que decidir algo (Escolha.mostrar, prova, controle livre): essas coisas não são puladas.
//   Cena.esperar(ms) ........ use no lugar de setTimeout nas cenas (pulando: resolve na hora)
//   Cena.marcar(sim) ........ as fases chamam a cada quadro: "estou numa cena agora?"
//   Cena.entrar() / sair() .. cenas fora das fases (ex.: a abertura do criador) marcam o começo e o fim
//   Cena.rodar(fn) .......... roda uma função de cena como cena (entrar/sair automático); Cena.pular() pula (o mesmo que o botão)
//   Cena.pulando ............ true enquanto pula; Cena.passos() = quantos passos de simulação dar por quadro (1, ou 25 pulando)
//   Cena.interativo() ....... chamado nas decisões do jogador: para de pular
// =====================================================================
const Cena = (() => {
  let pulando = false, manual = 0, marca = 0, btn = null, semCena = 0;
  const pend = new Set();
  function montar() {
    if (btn) return;
    const css = document.createElement('style');
    css.textContent = '#cenaPular { position: fixed; z-index: 40; top: calc(8px + env(safe-area-inset-top, 0px)); right: max(10px, env(safe-area-inset-right, 0px)); width: auto; min-width: 128px; height: 40px; padding: 0 12px; font-size: 12px; --p: var(--p2, 2px); white-space: nowrap; }\n#cenaPular[hidden] { display: none; }';
    document.head.appendChild(css);
    btn = document.createElement('button'); btn.id = 'cenaPular'; btn.type = 'button'; btn.className = 'pxBtn'; btn.hidden = true;
    btn.addEventListener('pointerdown', (e) => { e.preventDefault(); e.stopPropagation(); pular(); });
    btn.addEventListener('click', (e) => { e.preventDefault(); e.stopPropagation(); });
    ($('raizJogo') || document.body).appendChild(btn);
  }
  let congelado = false;
  const armar = (t) => { t.t0 = performance.now(); t.id = setTimeout(() => { pend.delete(t); t.r(); }, t.ms); };
  function esperar(ms) {
    if (pulando || !(ms > 0)) return new Promise((r) => setTimeout(r, 0));
    return new Promise((r) => { const t = { r, ms }; pend.add(t); if (!congelado) armar(t); });
  }
  function congelar(on) {                             // pausa global: as esperas das cenas param de contar e continuam depois
    if (on === congelado) return; congelado = on; const agora = performance.now();
    for (const t of pend) { if (on) { if (t.id != null) { clearTimeout(t.id); t.id = null; t.ms = Math.max(0, t.ms - (agora - t.t0)); } } else armar(t); }
  }
  // o botão só vale em cena COM FALA: a fala aberta, ou a fase marcando cena com uma fala nos últimos 2,5 s (ou já pulando).
  //   Portas, dormir, banho, pia, banheiro... (cenas sem fala) não mostram mais o "Pular cena".
  let ultFala = -1e9;
  const falando = () => typeof Dialogo !== 'undefined' && Dialogo.aberto();
  const ativa = () => manual > 0 || falando() || (performance.now() - marca < 250 && (pulando || performance.now() - ultFala < 2500));
  function pular() {
    if (pulando || !ativa()) return;
    pulando = true; semCena = 0;
    for (const t of pend) { if (t.id != null) clearTimeout(t.id); setTimeout(t.r, 0); }
    pend.clear();
    if (typeof Dialogo !== 'undefined') Dialogo.pularTudo();
    if (btn) btn.hidden = true;
  }
  const interativo = () => { pulando = false; };
  const marcar = (sim) => { if (sim) marca = performance.now(); };
  const entrar = () => { manual++; };
  const sair = () => { manual = Math.max(0, manual - 1); };
  async function rodar(fn) { entrar(); try { return await fn(); } finally { sair(); } }
  function tick() {                                   // (main loop) mostra/esconde o botão e encerra o pulo quando a cena acaba
    if (falando()) ultFala = performance.now();
    const a = ativa();
    if (!a) { if (++semCena > 3) pulando = false; } else semCena = 0;
    if (pulando && typeof Dialogo !== 'undefined' && Dialogo.aberto()) Dialogo.pularTudo();
    const escolhendo = !!document.querySelector('#escolha:not([hidden])');
    const pausa = $('pauseScreen'), mostra = a && !pulando && !escolhendo && !(pausa && !pausa.hidden);
    if (mostra) { montar(); const tx = T('Pular cena ▶'); if (btn.textContent !== tx) btn.textContent = tx; }
    if (btn && btn.hidden === mostra) btn.hidden = !mostra;
  }
  return { esperar, congelar, pular, interativo, marcar, entrar, sair, rodar, tick, passos: () => (pulando ? 25 : 1), get pulando() { return pulando; } };
})();

// A MARIPOSA (a mesma da Fase 1): aparece no alto da tela, por uns segundos, sempre que o que acabou de acontecer muda alguma coisa na
//   história (uma escolha, um hábito, uma resposta grossa...). Não trava o jogo: Mariposa.mostrar() devolve uma Promise que resolve quando
//   ela some, para quem quiser esperar. O texto explicativo só aparece na primeira vez (PERSONAGEM.mothTexto, o mesmo da Fase 1).
const Mariposa = (() => {
  let el = null, tm = 0, fimEm = 0, texto = false;
  function desenho() {
    const half = ['......a..', '.......a.', 'kk.....eo', 'kkkk..bbo', 'kbbkkkbwo', 'kbbbbkwkw', 'kkbbbkwwo', 'ykkbbkowo', 'yyykkkoyo', '.yyykkooy', '.yyyk.ooo', '..yy...oy'];
    const cor = { a: '#1b1410', e: '#c43a20', o: '#2a1c12', k: '#4a3320', b: '#8a6a3c', w: '#f0e2b8', y: '#e8a820' };
    const cv = document.createElement('canvas'); cv.width = 17; cv.height = 12; const g = cv.getContext('2d');
    half.forEach((row, y) => { for (let x = 0; x < 9; x++) { const c = cor[row[x]]; if (!c) continue; g.fillStyle = c; g.fillRect(x, y, 1, 1); g.fillRect(16 - x, y, 1, 1); } });
    return cv;
  }
  function montar() {
    if (el && el.isConnected) return;
    if (!document.getElementById('mariposaCss')) {
      const st = document.createElement('style'); st.id = 'mariposaCss';
      st.textContent = '#mariposaHist{position:fixed;z-index:60;left:50%;top:calc(10px + env(safe-area-inset-top,0px));transform:translateX(-50%);display:flex;flex-direction:column;align-items:center;gap:6px;opacity:0;transition:opacity .7s ease;pointer-events:none;}'
        + '#mariposaHist.on{opacity:1;}#mariposaHist canvas{width:85px;height:60px;image-rendering:pixelated;filter:drop-shadow(0 2px 0 #2a1206);}'
        + '#mariposaHist p{margin:0;max-width:84vw;text-align:center;font:700 12px/1.25 var(--font-display);letter-spacing:.04em;color:#fff0c8;text-shadow:0 2px 0 #2a1206,0 0 6px #000;}';
      document.head.appendChild(st);
    }
    el = document.createElement('div'); el.id = 'mariposaHist'; el.append(desenho(), document.createElement('p'));
    (document.getElementById('raizJogo') || document.body).appendChild(el);
  }
  function mostrar() {
    try {
      montar();
      const primeira = !PERSONAGEM.mothTexto; PERSONAGEM.mothTexto = true;
      const p = el.querySelector('p'); p.textContent = primeira ? T('Quando a mariposa aparece, é porque aquilo que acabou de acontecer vai afetar a história...') : ''; p.style.display = primeira ? '' : 'none';
      const dur = primeira ? 5200 : 2600; fimEm = Date.now() + dur; texto = primeira;
      void el.offsetWidth; el.classList.add('on'); clearTimeout(tm); tm = setTimeout(() => { if (el) el.classList.remove('on'); }, dur);
      return new Promise((ok) => setTimeout(ok, dur + 700));
    } catch (e) { console.warn('[Mariposa]', e); return Promise.resolve(); }
  }
  const visivel = () => Date.now() < fimEm;
  const comTexto = () => visivel() && texto;                           // com a explicação embaixo (quem escreve no alto da tela desce um pouco)
  return { mostrar, visivel, comTexto };
})();

const Escolha = (() => {                              // caixa de ESCOLHAS (reutilizável): Escolha.mostrar(titulo, ['op1', 'op2']) → Promise(índice)
  let el = null;
  function montar() {
    if (el) return;
    const css = document.createElement('style');
    css.textContent = `
#escolha { position: fixed; left: 0; right: 0; bottom: 0; z-index: 15; display: flex; justify-content: center; padding: 0 max(12px, env(safe-area-inset-right, 0px)) calc(12px + env(safe-area-inset-bottom, 0px)) max(12px, env(safe-area-inset-left, 0px));
  --mx-ink: #2a1206; --mx-creme: #fff0c8; --mx-laranja: #f0a020; color: var(--mx-creme); }
#escolha[hidden] { display: none; }
/* algumas escolhas (ex.: o balcão do seu Valdemar) pedem o meio da tela, não embaixo */
#escolha.centro { top: 0; align-items: center; padding-bottom: max(12px, env(safe-area-inset-bottom, 0px)); }
/* escolha SEM título com uma fala aberta (a pergunta já está na fala): os botões ficam em cima, sem cobrir a caixa da fala */
#escolha.sobreFala { top: 0; align-items: flex-start; padding-top: calc(10px + env(safe-area-inset-top, 0px)); }
#escolha .escTit[hidden] { display: none; }
#escolha .escCaixa { --p: var(--p3, 3px); box-sizing: border-box; width: min(720px, 100%); padding: 4px 6px 8px; display: flex; flex-direction: column; gap: 8px;
  border: solid transparent; border-width: calc(var(--p) * 7); border-image: var(--sp-escuro) 7 fill / calc(var(--p) * 7) stretch; image-rendering: pixelated; }
#escolha .escTit { margin: 0; font: 600 clamp(14px, 3.8vh, 19px)/1.3 var(--font-body); }
#escolha .pxBtn { --p: var(--p2, 2px); width: 100%; height: auto; min-height: 38px; padding: 4px 10px; font-size: 13px; line-height: 1.15; text-transform: none; letter-spacing: 0.02em; flex: 0 0 auto; }
/* (6.6.18) a lista de opções tem no máximo a altura de 3 opções: o resto fica embaixo, rolando (a caixa não cresce e não cobre a tela) */
#escolha .escLista { position: relative; display: flex; flex-direction: column; gap: 8px; overflow-y: auto; overscroll-behavior: contain; touch-action: pan-y;
  -webkit-overflow-scrolling: touch; scrollbar-width: thin; scrollbar-color: var(--mx-laranja) rgba(0, 0, 0, 0.25); }
#escolha .escLista.rola { padding-right: 6px; }
#escolha .escLista::-webkit-scrollbar { width: 6px; }
#escolha .escLista::-webkit-scrollbar-thumb { background: var(--mx-laranja); }
#escolha .escLista::-webkit-scrollbar-track { background: rgba(0, 0, 0, 0.25); }
#escolha .escMais { align-self: center; margin: -4px 0 -2px; font: 700 12px/1 var(--font-display); color: var(--mx-laranja); pointer-events: none; animation: escMaisPisca 1.1s steps(2) infinite; }
#escolha .escMais[hidden] { display: none; }
@keyframes escMaisPisca { 50% { opacity: 0.35; } }`;
    document.head.appendChild(css);
    el = document.createElement('div'); el.id = 'escolha'; el.hidden = true;
    ($('raizJogo') || document.body).appendChild(el);
  }
  // UMA escolha de cada vez: se outra pedir para abrir com uma aberta (ex.: o celular tocando no meio de uma conversa), ela
  // espera a de agora fechar. Antes a nova trocava os botões e a promessa da primeira NUNCA resolvia — o jogo ficava travado na cena.
  let fila = Promise.resolve();
  function mostrar(titulo, ops, opcoes) {
    const p = fila.then(() => abrir(titulo, ops, opcoes));
    fila = p.catch(() => {});
    return p;
  }
  function abrir(titulo, ops, opcoes) {
    if (typeof Cena !== 'undefined') Cena.interativo();      // decisão do jogador: o "Pular cena" para aqui
    montar();
    el.classList.toggle('centro', !!(opcoes && opcoes.centro));   // ex.: Escolha.mostrar(titulo, ops, { centro: true })
    el.innerHTML = '<div class="escCaixa" role="dialog"><p class="escTit"></p><div class="escLista">' + ops.map((o, i) => '<button type="button" class="pxBtn" data-i="' + i + '"></button>').join('') + '</div><div class="escMais" hidden>▼</div></div>';
    el.querySelector('.escTit').textContent = titulo || ''; el.querySelector('.escTit').hidden = !titulo;
    if (titulo && Dialogo.aberto()) Dialogo.esconder();      // UMA caixa só: a pergunta vira o título da escolha (a fala some)
    el.classList.toggle('sobreFala', !titulo && Dialogo.aberto());
    el.querySelectorAll('button').forEach((b, i) => { b.textContent = ops[i]; });
    el.hidden = false;
    limitarLista();
    return new Promise((res) => {
      el.onclick = (e) => {
        const b = e.target.closest('button[data-i]');
        if (!b) return;
        if (typeof Som !== 'undefined' && Som.clique) Som.clique();
        el.hidden = true; el.onclick = null; res(Number(b.dataset.i));
      };
    });
  }
  // (6.6.18) até 3 opções a caixa mostra tudo; com mais, ela fica com a altura das 3 primeiras e o resto rola (a setinha ▼ avisa que tem mais)
  function limitarLista() {
    const lista = el.querySelector('.escLista'), mais = el.querySelector('.escMais'), bs = lista.querySelectorAll('button');
    lista.style.maxHeight = ''; lista.classList.remove('rola'); lista.scrollTop = 0; mais.hidden = true; lista.onscroll = null;
    if (bs.length <= 3) return;
    const h = bs[2].offsetTop + bs[2].offsetHeight;                                  // offsetTop medido dentro da lista (position: relative)
    lista.style.maxHeight = Math.ceil(h + 1) + 'px';
    if (lista.scrollHeight <= lista.clientHeight + 2) return;
    lista.classList.add('rola');
    const ver = () => { mais.hidden = lista.scrollTop + lista.clientHeight >= lista.scrollHeight - 3; };
    lista.onscroll = ver; ver();
  }
  return { mostrar, aberta: () => !!(el && !el.hidden) };
})();

// textos novos da Fase 1: tutorial com bolas paradas (falta, lateral, escanteio), cena do "nem vi você passando" e o Professor Roberto no pátio
Object.assign(I18N, {
  'Antes de começar: em qual posição você quer jogar?': ['Before we start: which position do you want to play?', 'Antes de empezar: ¿en qué posición quieres jugar?', 'Prima di iniziare: in che ruolo vuoi giocare?', 'Avant de commencer : à quel poste veux-tu jouer ?'],
  'Em qual posição você quer jogar?': ['Which position do you want to play?', '¿En qué posición quieres jugar?', 'In che ruolo vuoi giocare?', 'À quel poste veux-tu jouer ?'],
  'Zagueiro: defender o nosso gol': ['Defender: protect our goal', 'Defensa: proteger nuestro arco', 'Difensore: difendere la nostra porta', 'Défenseur : protéger notre but'],
  'Meia: armar o jogo': ['Midfielder: build the play', 'Mediocampista: armar el juego', 'Centrocampista: costruire il gioco', 'Milieu : construire le jeu'],
  'Atacante: fazer gols': ['Striker: score goals', 'Delantero: hacer goles', 'Attaccante: fare gol', 'Attaquant : marquer des buts'],
  'Boa! Você fica lá atrás, protegendo o nosso gol.': ['Nice! You stay at the back, protecting our goal.', '¡Bien! Te quedas atrás, cuidando nuestro arco.', 'Bene! Stai dietro, a proteggere la nostra porta.', 'Bien ! Tu restes derrière, à protéger notre but.'],
  'Boa! Você fica no meio, distribuindo o jogo.': ['Nice! You stay in the middle, running the play.', '¡Bien! Te quedas en el medio, repartiendo el juego.', 'Bene! Stai in mezzo, a smistare il gioco.', 'Bien ! Tu restes au milieu, à distribuer le jeu.'],
  'Boa! Você fica lá na frente, atrás do gol deles.': ['Nice! You stay up front, going for their goal.', '¡Bien! Te quedas adelante, yendo por su arco.', 'Bene! Stai davanti, a caccia della loro porta.', 'Bien ! Tu restes devant, à la chasse au but adverse.'],
  "Eu não sei o que dizer, nunca tinha jogado antes, não sabia que ia me sair bem!": ["I don't know what to say, I had never played before, I didn't know I'd do this well!", "¡No sé qué decir, nunca había jugado antes, no sabía que me iría tan bien!", "Non so cosa dire, non avevo mai giocato prima, non sapevo che mi sarebbe andata così bene!", "Je ne sais pas quoi dire, je n'avais jamais joué avant, je ne savais pas que je m'en sortirais si bien !"],
  "Driblar! Eu vou ficar parado aqui, de marcador. Corra com a bola para cima de mim: quando eu estiver perto, aparece o botão DRIBLAR. Aperte nele na hora certa e acerte os toques na tela!": ["Dribbling! I'll stand right here as the defender. Run at me with the ball: when I'm close, the DRIBBLE button shows up. Press it at the right moment and hit the taps on screen!", "¡Regatear! Me voy a quedar aquí, de marcador. Corre hacia mí con la pelota: cuando esté cerca, aparece el botón REGATEAR. ¡Púlsalo en el momento justo y acierta los toques en la pantalla!", "Dribbling! Resto fermo qui, come avversario. Corri verso di me con il pallone: quando sono vicino, compare il pulsante DRIBBLA. Premilo al momento giusto e centra i tocchi sullo schermo!", "Dribbler ! Je reste ici, comme défenseur. Cours vers moi avec le ballon : quand je suis proche, le bouton DRIBBLER apparaît. Appuie au bon moment et réussis les touches à l'écran !"],
  "DRIBLAR: corra com a bola até o João e toque em DRIBLAR": ["DRIBBLE: run with the ball at João and tap DRIBBLE", "REGATEAR: corre con la pelota hacia João y toca REGATEAR", "DRIBBLARE: corri con il pallone verso João e tocca DRIBBLA", "DRIBBLER : cours avec le ballon vers João et touche DRIBBLER"],
  "Olha só! Você passou direitinho por mim!": ["Look at that! You got right past me!", "¡Mira! ¡Me pasaste sin problemas!", "Guarda! Mi hai superato benissimo!", "Regarde ! Tu m'as passé sans problème !"],
  "Agora vamos para as bolas paradas! Quando o jogo para, é você quem decide como a bola volta. Primeiro: a falta.": ["Now let's move on to set pieces! When play stops, you decide how the ball comes back. First: the free kick.", "¡Ahora vamos con las jugadas a balón parado! Cuando el juego se detiene, tú decides cómo vuelve la pelota. Primero: el tiro libre.", "Ora passiamo ai calci piazzati! Quando il gioco si ferma, sei tu a decidere come torna il pallone. Prima: la punizione.", "Passons maintenant aux coups de pied arrêtés ! Quand le jeu s'arrête, c'est toi qui décides comment le ballon revient. D'abord : le coup franc."],
  "Quando alguém é derrubado, o juiz apita e a gente cobra do lugar da falta. Você mira no gol, segura a força e solta na faixa verde, igual ao chute. Pode dar efeito na bola também!": ["When someone is fouled, the referee blows the whistle and we take the kick from where the foul happened. Aim at the goal, hold the power and release on the green band, just like a shot. You can add spin too!", "Cuando alguien es derribado, el árbitro pita y cobramos desde el lugar de la falta. Apuntas al arco, mantienes la fuerza y sueltas en la franja verde, igual que en el tiro. ¡También puedes darle efecto a la pelota!", "Quando qualcuno viene atterrato, l'arbitro fischia e battiamo dal punto del fallo. Mira alla porta, tieni premuta la forza e rilascia sulla fascia verde, come nel tiro. Puoi anche dare effetto al pallone!", "Quand un joueur est fauché, l'arbitre siffle et on tire depuis l'endroit de la faute. Tu vises le but, tu maintiens la puissance et tu relâches sur la bande verte, comme pour un tir. Tu peux aussi donner de l'effet au ballon !"],
  "FALTA: cobre a falta em direção ao gol": ["FREE KICK: take the free kick toward the goal", "TIRO LIBRE: cobra el tiro libre hacia el arco", "PUNIZIONE: batti la punizione verso la porta", "COUP FRANC : tire le coup franc vers le but"],
  "Que golaço de falta! Você leva jeito!": ["What a free-kick goal! You've got talent!", "¡Qué golazo de tiro libre! ¡Tienes talento!", "Che gol su punizione! Hai talento!", "Quel but sur coup franc ! Tu as du talent !"],
  "Falta é assim mesmo: cada uma tem um segredo. Vamos treinando!": ["Free kicks are like that: each one has its secret. Let's keep practicing!", "Los tiros libres son así: cada uno tiene su secreto. ¡Sigamos practicando!", "Le punizioni sono così: ognuna ha il suo segreto. Continuiamo ad allenarci!", "Les coups francs, c'est comme ça : chacun a son secret. Continuons à nous entraîner !"],
  "Agora o lateral. Na quadra de futsal ele é cobrado com o pé: a bola fica no chão, na linha lateral.": ["Now the throw-in. On a futsal court it's taken with the foot: the ball sits on the ground, on the sideline.", "Ahora el saque de banda. En la cancha de futsal se saca con el pie: la pelota queda en el suelo, en la línea lateral.", "Ora la rimessa laterale. Nel futsal si batte con il piede: il pallone sta a terra, sulla linea laterale.", "Maintenant la remise en jeu. En futsal, elle se fait au pied : le ballon est posé au sol, sur la ligne de touche."],
  "Quando a bola sai pela lateral, o jogo recomeça de lá. Aqui você toca em PASSAR, mira em mim e escolhe a força do toque. Vai!": ["When the ball goes out on the side, play restarts from there. Here you tap PASS, aim at me and choose how hard to kick it. Go!", "Cuando la pelota sale por la banda, el juego se reanuda desde ahí. Aquí tocas PASAR, apuntas hacia mí y eliges la fuerza del toque. ¡Vamos!", "Quando il pallone esce dalla linea laterale, il gioco riparte da lì. Qui tocchi PASSA, mira verso di me e scegli la forza del tocco. Vai!", "Quand le ballon sort sur le côté, le jeu reprend de là. Ici, tu touches PASSER, tu me vises et tu choisis la force de la touche. Vas-y !"],
  "LATERAL: devolva a bola para o João": ["THROW-IN: pass the ball back to João", "SAQUE DE BANDA: devuélvele la pelota a João", "RIMESSA: restituisci il pallone a João", "REMISE EN JEU : redonne le ballon à João"],
  "Boa! Um lateral bem cobrado mantém a bola com o seu time.": ["Nice! A well-taken throw-in keeps the ball with your team.", "¡Bien! Un saque de banda bien hecho mantiene la pelota en tu equipo.", "Bene! Una rimessa fatta bene tiene il pallone alla tua squadra.", "Bien ! Une remise en jeu bien faite garde le ballon dans ton équipe."],
  "E por fim o escanteio: quando a bola sai pela linha de fundo depois de tocar no time que defende, a gente cobra do cantinho. Hora de cruzar na área!": ["And finally the corner kick: when the ball goes out over the end line after touching the defending team, we take it from the corner. Time to cross into the box!", "Y por último el tiro de esquina: cuando la pelota sale por la línea de fondo tras tocar al equipo que defiende, cobramos desde la esquina. ¡Hora de centrar al área!", "E infine il calcio d'angolo: quando il pallone esce sulla linea di fondo dopo aver toccato la squadra che difende, si batte dall'angolo. È il momento di crossare in area!", "Et enfin le corner : quand le ballon sort sur la ligne de fond après avoir touché l'équipe qui défend, on tire depuis le coin. C'est l'heure de centrer dans la surface !"],
  "Eu vou ficar na área esperando a bola. Você cobra o escanteio do cantinho: mire em mim, escolha a força e cruze!": ["I'll wait in the box for the ball. You take the corner from the corner arc: aim at me, choose the power and cross it!", "Yo me quedo en el área esperando la pelota. Tú cobras el córner desde la esquina: apunta hacia mí, elige la fuerza y ¡centra!", "Io resto in area ad aspettare il pallone. Tu batti l'angolo dalla bandierina: mira verso di me, scegli la forza e crossa!", "Je reste dans la surface à attendre le ballon. Toi, tu tires le corner depuis le coin : vise-moi, choisis la force et centre !"],
  "ESCANTEIO: cruze a bola para o João, na área": ["CORNER: cross the ball to João in the box", "CÓRNER: centra la pelota hacia João, en el área", "ANGOLO: crossa il pallone verso João, in area", "CORNER : centre le ballon vers João, dans la surface"],
  "Perfeito! Agora você conhece as bolas paradas: falta, lateral e escanteio.": ["Perfect! Now you know set pieces: free kick, throw-in and corner.", "¡Perfecto! Ahora conoces las jugadas a balón parado: tiro libre, saque de banda y córner.", "Perfetto! Ora conosci i calci piazzati: punizione, rimessa e angolo.", "Parfait ! Tu connais maintenant les coups de pied arrêtés : coup franc, remise en jeu et corner."],
  "Pronto! Agora a gente joga de verdade. Vamos lá!": ["Done! Now we play for real. Let's go!", "¡Listo! Ahora jugamos en serio. ¡Vamos!", "Fatto! Ora giochiamo sul serio. Andiamo!", "Prêt ! Maintenant on joue pour de vrai. Allons-y !"],
  "Eita, eu nem vi você passando para a quadra...": ["Whoa, I didn't even see you slip into the court...", "Vaya, ni te vi pasar a la cancha...", "Accidenti, non ti ho nemmeno visto entrare in campo...", "Ben ça alors, je ne t'ai même pas vu passer sur le terrain..."],
  "Você está lento demais, João!": ["You're way too slow, João!", "¡Eres demasiado lento, João!", "Sei troppo lento, João!", "Tu es trop lent, João !"],
  "Olá, {0}! Estou de olho na minha turma até os pais virem buscar.": ["Hello, {0}! I'm keeping an eye on my class until their parents come to pick them up.", "¡Hola, {0}! Estoy vigilando a mi clase hasta que los padres vengan a recogerlos.", "Ciao, {0}! Sto sorvegliando la mia classe finché i genitori non vengono a prenderli.", "Bonjour, {0} ! Je surveille ma classe en attendant que les parents viennent la chercher."],
  "Eles adoram uma bola, mas comigo ninguém sai do meu campo de visão!": ["They love a ball, but nobody leaves my sight!", "¡Les encanta una pelota, pero conmigo nadie sale de mi campo de visión!", "Adorano il pallone, ma con me nessuno esce dal mio campo visivo!", "Ils adorent le ballon, mais avec moi personne ne sort de mon champ de vision !"],
  "Os pais já já chegam. Por enquanto, eu fico de olho na turma.": ["The parents will be here soon. Until then, I'm keeping an eye on the class.", "Los padres llegan pronto. Mientras tanto, vigilo a la clase.", "I genitori arrivano presto. Intanto tengo d'occhio la classe.", "Les parents arrivent bientôt. En attendant, je garde un œil sur la classe."],
});
// ---------------------------------------------------------------------
// DADOS DA HISTÓRIA: os meninos da quadra e os uniformes. As cenas (Fase1) e a partida (Historia)
// usam estes mesmos dados, então os bonecos são iguais nas duas. Corpo 68% e cabeça 155% (modo "bebê").
// ---------------------------------------------------------------------
const HIST = (() => {
  const pele = (i) => PELES_FITZ[i].cor, cab = (i) => CORES_CABELO[i].cor;
  const ci = (n) => Math.max(0, ESTILOS_CABELO.findIndex((c) => c.nome === n)), ri = (n) => Math.max(0, ROSTOS.findIndex((r) => r.nome === n));
  const k = (nome, p, c, est, ros, labio) => ({ nome, pele: pele(p), cabelo: cab(c), estilo: ci(est), rosto: ri(ros), labio: labio == null ? 3 : labio });
  return {
    crianca: { cabecao: 1.55, escala: 0.68 },
    uni0: { camisa: '#f2c230', listra: '#111111', gola: '#111111', calcao: '#1b1d22', meia: '#f2c230', sola: '#111111', goleiro: '#2a72d6' },
    uni1: { camisa: '#c8352b', listra: '#f2f2ee', gola: '#7e1e17', calcao: '#1b1d22', meia: '#c8352b', sola: '#f2f2ee', goleiro: '#1f9e5c' },
    joao: k('João', 2, 0, 'Franja', 'Sorridente'),
    cadu: k('Sérgio', 4, 0, 'Black power', 'Sorridente'), bia: k('Bia', 3, 2, 'Coque longo', 'Padrão', 1),
    tadeu: k('Tadeu', 1, 3, 'Moicano', 'Sério'), duda: k('Duda', 2, 4, 'Longo liso', 'Sorridente', 0),
    nando: k('Nando', 5, 0, 'Dreads curtos', 'Padrão'), leo: k('Léo', 0, 1, 'Franja', 'Sonolento'),
    // (7.4.19) a Lúcia (a mesma da sala: pele 1, cabelo 4, rabo de cavalo) e o Vítor, o quinto da turma do Roberto
    lucia: k('Lúcia', 1, 4, 'Rabo de cavalo', 'Padrão', 2), vitor: k('Vítor', 3, 1, 'Topete', 'Padrão'),
    // o Professor Roberto: o MESMO modelo é o do juiz na partida (PARTIDA.arbitro) e o do professor vigiando a turma no pátio
    professor: { nome: 'Professor Roberto', pele: pele(1), cabelo: cab(6), estilo: ci('Franja'), rosto: ri('Padrão'), camisa: '#e9e9e4', listra: '#e9e9e4', gola: '#2a4f9a', calcao: 0x22252c, meia: '#e9e9e4', cabecao: 1.3, escala: 0.98 },
    // figurantes do pátio (alunos conversando); a roupa é a de escola de sempre
    figurantes: [k('Ana', 2, 2, 'Rabo de cavalo', 'Sorridente', 2), k('Bruna', 4, 0, 'Cacheado longo', 'Padrão', 4), k('Caio', 1, 1, 'Curto', 'Padrão'), k('Davi', 3, 0, 'Raspado', 'Sério'),
      k('Elisa', 0, 5, 'Coque com degradê', 'Sorridente', 1), k('Fábio', 2, 3, 'Topete', 'Padrão'), k('Gui', 5, 0, 'Corte baixo', 'Sorridente'), k('Hugo', 3, 2, 'Bagunçado', 'Sonolento')],
  };
})();

